COLLDATA("tadabburur","ur",[[473,"§غافر\ndeeds\nایسے گناہوں كو یاد كیجئے جنہیں آپ نے انجام دیا ہو، پھر ان سے زیاده سے زیاده توبہ و استغفار كیجئے.\nصبح وشام سو سو مرتبہ (سُبْحَانَ اللّٰهِ وَبِحَمْدِهٖ) (اللہ تعالیٰ اپنی تعریف سمیت پاک ہے) پڑهئے.\nتكبر سے الله كى پناه مانگئے ؛ كیونكہ یہ قبول حق سے روكتا ہے.\nguid\nراه ِ حق میں صبر وثبات كا مظاہره كریں ، یہى آپ كو یقین دلائےگا كہ الله كا وعده حق ہے.\nحق كو مٹانے كیلئے اكثر جو لوگ جھگڑتےہیں وه تكبر كى بنیاد پر جھگڑتےہیں.\nجو بڑى چیز کی تخلیق پر قادر ہو اس کے لئے كمزور شئی پیدا كرنا زیادہ آسان ہے.\nrefl\nقَالُوٓاْ أَوَ لَمۡ تَكُ تَأۡتِيكُمۡ رُسُلُكُم بِٱلۡبَيِّنَٰتِۖ قَالُواْ بَلَىٰۚ قَالُواْ فَٱدۡعُواْۗ وَمَا دُعَٰٓؤُاْ ٱلۡكَٰفِرِينَ إِلَّا فِي ضَلَٰلٍ ٥٠\nیعنى جس طرح تم نے دنیا میں اپنی آراء و افکار کو اہمیت دیتے ہوئے رسولوں سے اعراض كرنے كا فیصلہ لیا اسى طرح آج تم اپنے معاملے كى ذمہ داری بھی خود اٹھاؤ ، اور خود ہی الله سے دعا كرو۔ (ابن عاشور: ۲۴؍۱۶۶)\nمشركوں كا خود ہی اپنے لئے دعا كرنےکے حکم كا ماقبل کی زندگی سے کیا تعلق ہے؟\nوَمَا دُعَٰٓؤُاْ ٱلۡكَٰفِرِينَ إِلَّا فِي ضَلَٰلٍ ٥٠\nكفر تمام اعمال برباد كرنے والا اور قبولیت دعا سے روكنے والا ہے۔ (السعدى: ۷۳۹)\nبعض ان برے انجام و نقصانات كا ذكر كریں جو كافروں كو ان كے كفر كى وجہ سے لاحق ہوں گے؟\nإِنَّا لَنَنصُرُ رُسُلَنَا وَٱلَّذِينَ ءَامَنُواْ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَيَوۡمَ يَقُومُ ٱلۡأَشۡهَٰدُ ٥١\n(رسولوں اور مومنوں کی مدد کیسے ہوتی ہے اس سلسلہ میں) ابن عباس رضی اللہ عنہما نے كہا: غلبہ اور طاقت كے ذریعے۔ اور ضحاك نے كہا: دنیا میں حجت كے ذریعے اور آخرت میں عذر كےذریعے۔ اور كہاگیا: دنیا وآخرت میں دشمنوں سے انتقام لیكر۔ اور یہ سارى چیزیں انبیاء اور مومنوں كو حاصل ہوئیں۔ چنانچہ یہ لوگ حجت ودلیل سے اپنے مخالفین پرغالب رہتےہیں ، اور الله نے دشمنوں كوہلاک و برباد كركےاور ان پر غلبہ دیكر ان كى مدد کی، اور دشمنوں كےہاتھوں شہید ہونے كےبعد بھى دشمنوں سے انتقام لے کر ا ن كى مدد فرمائى جیسا كہ یحیى بن زكریا- علیہما السلام- كى مدد فرمائى جب انہیں شہید كردیاگیا ، تو ان كى وجہ سےانتقاماً ستر ہزار دشمنوں كو قتل كیا گیا، بہرحال سابقہ صورتوں میں سے کسی نہ کسی صورت سے ان کی مدد ہوئی ہے ۔(البغوى: ۴؍۴۷)\nكیا مدد الہى صرف رسولوں كےساتھ خاص ہے؟ اور كیا اللہ کی مدد دشمنوں كى ہلاكت پر موقوف ہے؟\nوَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡهُدَىٰ وَأَوۡرَثۡنَا بَنِيٓ إِسۡرَٰٓءِيلَ ٱلۡكِتَٰبَ ٥٣\nالله تعالىٰ کی طرف سے اپنے رسولوں اور مومنوں كى مدد کی یہ بہت ہى واضح مثال ہے،اور نصرت و مدد کی یہ مثال اس مدد و نصرت سے بہت زیادہ مشابہت و مماثلت رکھتی ہے جس کو اللہ تعالیٰ نے اپنے نبی کریم صلی اللہ علیہ وسلم اور مومنوں کے لئے مقدر کررکھاتھا؛ كیونكہ قوم فرعون پر موسیٰ علیہ السلام كى مدد كیوجہ سے الله نے ایك ایسی عظیم امت كو برپا کیا جس کی پہلے کوئی اہمیت نہیں تھی اور انہیں ایك عظیم شریعت اور ایك عظیم بادشاہت سے نوازا ،اسی طرح نبى کریم صلی اللہ علیہ وسلم اور مومنوں كى مدد ہوئی، بلكہ اس سے بھى عظیم، كامل اور لائق شرف امت، شریعت اور حکومت انہیں دی گئی۔ (ابن عاشور: ۲۴؍۱۶۹)\nمومنوں كیلئے نصرت الہى پر موسیٰ علیہ السلام كا واقعہ كیسے ایك واضح مثال ہے؟\nإِنَّ ٱلَّذِينَ يُجَٰدِلُونَ فِيٓ ءَايَٰتِ ٱللَّهِ بِغَيۡرِ سُلۡطَٰنٍ أَتَىٰهُمۡ إِن فِي صُدُورِهِمۡ إِلَّا كِبۡرٞ مَّا هُم بِبَٰلِغِيهِۚ\nیعنى ایسا تكبر اور گھمنڈ ان کے دلوں میں ہے جو انہیں آپ كى پیروى كرنے اور بات ماننے سے روكے رکھا ہے۔ (ابن جزى: ۲؍۲۸۳)\nنبى كریم صلی اللہ علیہ وسلم كى اتباع كرنے سے كافروں كو كس چیز نے روك ركھا تھا؟\nإِنَّ ٱلَّذِينَ يُجَٰدِلُونَ فِيٓ ءَايَٰتِ ٱللَّهِ بِغَيۡرِ سُلۡطَٰنٍ أَتَىٰهُمۡ إِن فِي صُدُورِهِمۡ إِلَّا كِبۡرٞ مَّا هُم بِبَٰلِغِيهِۚ\nاللہ کی آیتوں میں بحث و جدال کے لئےدلیل كى قید لگانے کا فائدہ ان کے بحث و تکرار کی قباحت و شناعت کوبیان کرنا ہے، ورنہ الله كى نشانیوں میں بحث و مباحثہ بغیر دلیل و حجت ہی کے کیا جائےگا ، كیونكہ الله كى نشانیاں واقع كےخلاف ہوتى ہى نہیں ہیں، لہٰذا یہ قید اس قید کی نظیر ہے جو اس آیت میں آئى ہے: ﴿وَمَنۡ أَضَلُّ مِمَّنِ ٱتَّبَعَ هَوَىٰهُ بِغَيۡرِ هُدٗى مِّنَ ٱللَّهِ﴾ [القصص: ۵۰]۔(ابن عاشور: ۲۴؍۱۷۳)\nالله كى نشانیوں میں بحث ومباحثہ پر دلیل کی قید کا کیا فائدہ ہے؟\nوَمَا يَسۡتَوِي ٱلۡأَعۡمَىٰ وَٱلۡبَصِيرُ وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَلَا ٱلۡمُسِيٓءُۚ قَلِيلٗا مَّا تَتَذَكَّرُونَ ٥٨\nیہاں بصیر سے پہلے اعمى كا ذكر كیا گیا باوجودیكہ بصارت وبینائی ایک ذات کے اندر اندھے پن كےمقابلے زیاده لائق شرف ہے اور بصیر سے جس كى تشبیہ دى گئى ہے وه زیاده لائق شرف ہے بنسبت اس كے جس كى تشبیہ اعمى سے آئی ہے، کیونکہ بصیر سے مومنوں کو تشبیہ دى گئى ہے (اور اعمیٰ سے کافروں کو تشبیہ دی گئی ہے)پھر بھی كافروں كى تشبیہ کو اس لئے مقدم كیاگیا کیونکہ ان کے بحث وتکرار کی حالت بیان کرنا یہاں زیادہ اہم ہے ، کیونکہ وعظ ونصیحت کے مقصود وہی لوگ ہیں۔ (ابن عاشور: ۲۴؍۱۷۸)\nبصیر پر اعمى كو مقدم كیوں كیا گیا باوجودیكہ بصیر زیاده لائق شرف ہے؟\nwords\nالأَشهَادُجو جھوٹوں پر گواهي دے گا(ملائكه اور انبياء).\nمَعذِرَتُهُمان كا عذر پيش كرنا.\nلأِولِي الأَلبَابِعقل سليم والے.\nبِالعَشِيِّ وَالإِبكَارِدن كے آخر ميں او ردن كے شروع ميں.\nسُلطَانٍحجت ؛ دليل۔ برھان.\nمَا هُم بِبَالِغِيهِوه آپ پر خاص انعامات تك پهنچنے والے نهيں."],[474,"§غافر\ndeeds\nآج زیاده سے زیاده دعا كریں تاكہ دعا سے بھاگنے اور تكبر كرنے والوں میں سے نہ ہوجائیں.\nآج ایسا كوئى کام كریں جس میں اپنے رب كیلئے عاجزى وخاكسارى كا اظہار ہو.\nآج رات جلدى سوئیں اورجلدى بیدار ہوجائیں ، تاكہ اس طبیعت اور فطرت كے موافق ہوجائیں جس پر الله نے آپ كو پیدا كیا ہے.\nguid\nاس میں الله كےانعام واحسان كا بیان ہے اور الله تعالىٰ كے شكریے كامطالبہ.\nقیامت قریب ہے، سوچئے آپ نے اس كیلئے كیا تیارى كرركھى ہے؟\nاپنے تمام كاموں میں خلوص وللہیت پیدا كریں.\nrefl\nوَقَالَ رَبُّكُمُ ٱدۡعُونِيٓ أَسۡتَجِبۡ لَكُمۡۚ إِنَّ ٱلَّذِينَ يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِي سَيَدۡخُلُونَ جَهَنَّمَ دَاخِرِينَ ٦٠\n(يستكبرون عن عبادتي) یعنى مجھ سے بےرغبت ہوكر تكبر كرتےہیں، جیسا كہ نبى كریم صلی اللہ علیہ وسلم نےفرمایا: (جو الله سے نہیں مانگتا وه اس پر غضبناك ہوتا ہے)۔ اور آپ صلی اللہ علیہ وسلم كا یہ فرمان: (دعا ہى عبادت ہے)۔ تو اس كا مفہوم یہ ہے كہ دعا اور الله كى طرف رغبت ہى عبادت ہے، كیونكہ دعا كے اندر بندے كى عاجزى اور الله سے خاكسارى ظاہر ہوتى ہے۔(ابن جزى: ۲؍۲۸۴)\nاس آیت سے ہم كیسے یہ استدلال كرسكتےہیں كہ دعا ہى عبادت ہے؟\nوَقَالَ رَبُّكُمُ ٱدۡعُونِيٓ أَسۡتَجِبۡ لَكُمۡۚ إِنَّ ٱلَّذِينَ يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِي سَيَدۡخُلُونَ جَهَنَّمَ دَاخِرِينَ ٦٠\nسفیان ثورى كہتےتھے: اے وه ذات! جس كےنزدیك سب سے محبوب وه بنده ہے جو اس سے زیاده سے زیاده مانگے، اور اے وه ذات! جس كے نزدیك سب سے زیاده مبغوض وه بنده ہے جو اس سے نہ مانگے، اور اے میرے رب!تیری طرح تیرے علاوه كوئى ایسى ذات نہیں۔ اسى مفہوم میں شاعر كہتاہے: الله غضبناك ہوتا ہے جب آپ اس سے سوال نہیں كرتے ، جبكہ ابن آدم اس وقت غضبناك ہوتا ہے جب اس سے سوال كیا جاتاہے۔(ابن كثیر: ۴؍۸۷)\nالله سے سوال كرنے اور لوگوں سے مانگنے میں کیا فرق ہے؟ دونوں میں موازنہ کیجئے.\nإِنَّ ٱلَّذِينَ يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِي سَيَدۡخُلُونَ جَهَنَّمَ دَاخِرِينَ ٦٠\nیعنى ذلیل اور رسوا ہوكر (ایسے لوگ جہنم میں داخل ہوں گے)۔ تكبر اور ہٹ دھرمى كى وجہ سے عذا ب اور رسوائى دونوں ان پر مسلط ہوں گے۔ (السعدى: ۷۴۱)\nاس آیت كى روشنى میں قاعده: (الجزاء من جنس العمل) پر روشنى ڈالئے.\nٱللَّهُ ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ قَرَارٗا وَٱلسَّمَآءَ بِنَآءٗ\nچونكہ اس آیت کا پہلا مقصد بندوں پراللہ کے احسان کواجاگر كرنا ہے – جیسا كہ قول بارى تعالىٰ : (لَكُم) سے پتہ چل رہاہے۔ اسی لئے آسمان پر زمین كو مقدم كیا گیا ہے؛ كیونكہ اس سے فائده اٹھانا حسى ہے، اور آسمان كا ذكر اس كےبعد كیا گیا كہ چیزوں کو ان کی ضد سے جانا جاتا ہے۔ (ابن عاشور: ۲۴؍۱۸۹)\nآیت كریمہ میں آسمان پر زمین كو مقدم كیوں كیا گیا؟\nوَصَوَّرَكُمۡ فَأَحۡسَنَ صُوَرَكُمۡ\nمقاتل نےكہا: اس نے تمہیں پیدا کیا اور بہترین سانچے میں ڈھالا ہے۔ ابن عباس رضی اللہ عنہما نے فرمایا: الله تعالىٰ نے ابن آدم كو معتدل القامت پیدا کیا ہے اپنےہاتھ سے اٹھا کر کھاتا پیتا ہے، جبکہ ابن آدم كےعلاوه دوسرى مخلوقات اپنے منہ سے كھاتی پیتی ہیں۔(البغوى: ۴؍۵۲)\nدوسرى تمام مخلوقات كى خلقت پر ابن آدم كى خلقت کو كیا امتیاز حاصل ہے ؟ اسے واضح كریں.\nوَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِۚ\nپاك یعنى لذت بخش چیزیں ؛ كیونكہ پاك چیزوں كا تذكره انعام واحسان كے سیاق میں آیا ہے، اس لئے اس سے مراد لذت بخش چیزیں ہوں گى، اور جب اس كا تذكره تحلیل وتحریم كےسیاق میں ہوگا تو اس سے مراد حلال وحرام کا بیان ہوگا۔ (ابن جزى: ۲؍۲۸۴)\nطیبات كا ذكر قرآن كریم كےاندر دو معنوں كیلئے استعما ل كیا گیا ہے؟ دونوں كو واضح کیجئے.\nوَأُمِرۡتُ أَنۡ أُسۡلِمَ لِرَبِّ ٱلۡعَٰلَمِينَ ٦٦\nیعنى میں رب العالمین كے سامنے سرتسلیم خم كرتاہوں، اسكے تابع ہوں اور خاكسارى كا اظہار كرتاہوں۔(القرطبى: ۱۸؍۳۷۸)\nالله تعالىٰ كیلئےسرتسلیم خم كیسے ہوگا؟\nwords\nلاَ رَيبَ فِيهَااس ميں كوئي شك نهيں.\nدَاخِرِينَچھوٹے حقير ذليل.\nلِتَسكُنُواروشن.\nمُبصِرًامُضِيئًا.\nفَأَنَّى تُؤفَكُونَتم ايمان سے كيسے روگرداني كرتے هو.\nيُؤفَكُوه اسے موڑتا هے."],[475,"§غافر\ndeeds\nارزل عمر كو پہونچنے سے الله كى پناه طلب كریں.\nصحیح بخاری سےانبیاء كےقصوں كا مطالعہ كریں.\nایسے غافل شحض كےبارےمیں غور وفكر كریں جو كسى فاسد عمل میں مبتلا ہو اور اس پر خوش بھى، پھر الله كا شكر ادا كریں كہ جس نے آپ كو اس سے عافیت میں ركھا.\nguid\nحق كو باطل میں بدلنے كیلئے جھگڑا كرنے والوں كا حشر بہت برا ہوگا.\nاگر ملك میں باطل پر خوشیوں كا اظہار كیا جانے لگے ، تو عذاب كا خوف بڑھ جاتا ہے.\nالله كى معصیت، اس كى اطاعت اور اس كى تقدیر پر صبر كریں، كیونكہ الله كى مدد اور كشادگى دور نہیں قریب ہے.\nrefl\nإِذِ ٱلۡأَغۡلَٰلُ فِيٓ أَعۡنَٰقِهِمۡ وَٱلسَّلَٰسِلُ يُسۡحَبُونَ ٧١\nحسن بن ابى الحسن نےكہا: دوزخیوں كى گردنوں میں زنجیریں اس لئے نہیں ڈالى جائیں گى كہ انہوں نے رب ذوالجلال كو عاجز كردیا ہے بلكہ اسلئے كہ شعلوں کے بجھنے کے بعد یہ زنجیریں انہیں جہنم کی گہرائیوں میں دھنسا لے جائیں گی۔ (ابن عطیہ : ۴؍۵۶۹)\nدوزخیوں كى گردنوں میں زنجیریں كیوں ڈالى جائیں گى؟\nفِي ٱلۡحَمِيمِ ثُمَّ فِي ٱلنَّارِ يُسۡجَرُونَ ٧٢\nیہ آپ كے قول : (سجرت التنور) سے ماخوذ ہے ، جب اسے آپ آگ سے بھر دیں، اور یہاں مفہوم یہ ہےكہ وه جہنم میں ویسے ہى ڈالے جائیں گے جیسے تنور میں ایندھن ڈالا جاتاہے، اسى لئے مجاہد نے اس كى تفسیر میں كہا: یہ آگ کے ایندھن بنیں گے۔ (ابن جزى: ۲؍۲۸۵)\nالله كى نشانیوں میں بغیر علم كے بحث ومباحثہ كرنے كى سنگینى كا اندازہ ان آیتوں سے كیسے ہوتا ہے؟\nثُمَّ قِيلَ لَهُمۡ أَيۡنَ مَا كُنتُمۡ تُشۡرِكُونَ ٧٣ مِن دُونِ ٱللَّهِۖ قَالُواْ ضَلُّواْ عَنَّا بَل لَّمۡ نَكُن نَّدۡعُواْ مِن قَبۡلُ شَيۡـٔٗاۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ ٱلۡكَٰفِرِينَ ٧٤\n(ثم قيل لهم أين ما كنتم تشركون) یعنى تم الله كو چھوڑ كر جن معبود ان باطلہ اور بتوں كى عبادت كرتےتھے، جنہیں مدد كیلئے پكارتےتھے، وه كہاں ہیں؟ انہیں مصیبت کی گھڑی میں تمہارے کام آنا چاہئے اور تمہیں عذاب سے بچانا چاہئے؛ كیونكہ معبود اپنے بندے كى مدد كرتاہے، اس طرح كى بات انہیں ڈانٹنے پھٹکارنے اور دنیا میں ان کے باطل كرتوتوں پر ملامت کے لئے ہوگی۔ (الطبرى: ۲۱؍۴۱۶)\nعذاب كے وقت الله تعالىٰ كا مشركوں سے ان كے معبودان باطلہ كےبارے میں سوال كرنے كا كیافائده ہے؟\nثُمَّ قِيلَ لَهُمۡ أَيۡنَ مَا كُنتُمۡ تُشۡرِكُونَ ٧٣\nیہاں استفہام کا مطلب غلطیوں پر انہیں تنبیہ کرنا اور میدان محشر میں ان كى فضیحت ہے؛ كیونكہ ان كا گمان تھا كہ وه بتوں كى عبادت اس لئے كرتےہیں كہ وه الله كے غضب سے ان كیلئے سفارشی بنیں گے، لیكن جب عذاب الہى ان كے حق میں ثابت ہوجائےگا اور وہاں وه كوئى سفارشى نہیں پائیں گے تو اس وقت انہیں ان کے گمان کی یاددہانی کروائی جائے گی اور ان سے كہاجائےگا: (أين ما كنتم تشركون) یعنى جن چیزوں كو شریك ٹھہراتےتھے وه كہاں ہیں؟ (ابن عاشور: ۲۴؍۲۰۴)\nآیت كریمہ میں استفہام كا كیا فائده ہے؟\nذَٰلِكُم بِمَا كُنتُمۡ تَفۡرَحُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَبِمَا كُنتُمۡ تَمۡرَحُونَ ٧٥\nیعنى یہ عذاب تمہیں ان گناہوں كے بدلے میں ملےہیں جن پر تم نازاں وفرحاں تھے، اور ایسا انہیں بطور توبیخ اور ڈانٹ كےكہاجائےگا، یعنى یہ عذاب تمہیں اس لئےملا ہے كہ تم دنیا میں معصیت، مال وصحت اور پیروكاروں كى كثرت پر خوشی و مسرت كا اظہار كرتےتھے۔ (القرطبى: ۱۸؍۳۸۳)\nان پر عذاب كےآنے كاسبب كیا بنا؟ اور ہمارےلئےاس میں كیا نصیحت ہے؟\nذَٰلِكُم بِمَا كُنتُمۡ تَفۡرَحُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَبِمَا كُنتُمۡ تَمۡرَحُونَ ٧٥\nیعنى تم اپنے باطل عقیدہ و عمل پر خوش ہو ، اور یہى وه مذموم خوشى ہے جو باعث عذاب ہے، برخلاف اس ممدوح خوشى كے جس كےبارےمیں الله تعالىٰ نے فرمایا: ﴿قُلۡ بِفَضۡلِ ٱللَّهِ وَبِرَحۡمَتِهِۦ فَبِذَٰلِكَ فَلۡيَفۡرَحُواْ﴾ [يونس: ۵۸] ا ور یہ خوشى علم نافع اور عمل صالح كى ہے۔(السعدى: ۷۴۳)\nممدوح یعنى اچھى خوشى كیا ہے اور مذموم خوشى كیا ہے؟\nفَٱصۡبِرۡ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞۚ فَإِمَّا نُرِيَنَّكَ بَعۡضَ ٱلَّذِي نَعِدُهُمۡ أَوۡ نَتَوَفَّيَنَّكَ فَإِلَيۡنَا يُرۡجَعُونَ ٧٧\nیعنى اگر ہم آپ كو وہ عذاب دكھا دیں جس كا وعده ہم نے ان سےكیا ہے تو اس سے آپ كى آنكھوں كو ٹھنڈك مل جائےگى، اور اگر آپ كو انہیں عذاب دینے سے پہلے ہی وفات دے دی تو وه تو میرے ہى پاس آنے والےہیں ، پھر ہم ان سے برى طرح انتقام لیں گے۔ (ابن جزى: ۲؍۲۸۶)\nفرمان بارى: (فإما نرينك) كےاندر نبى كریم صلی اللہ علیہ وسلم كیلئے تسلى ہے ، اسے واضح كریں.\nwords\nعَلَقَةٍرحم كے ساتھ لٹكا هوا گاڑھا خون/ لوتھڑا.\nلِتَبلُغُوا أَشُدَّكُمتاكه تمهاري قوت كامل هو جائے.\nأَنَّى يُصرَفُونَوه كيسے اس كي صحت سے روگرداني كرتے هيں.\nيُسجَرُونَان پر آگ بھڑكائي جائے گي.\nضَلُّوا عَنَّاهماري آنكھوں سے اوجھل هو گئے.\nتَمرَحُونَتم خوشي ميں بے جا وسعت كا اظهار كرتے هو.\nمَثوَىٹھكانا/ رهائش."],[476,"§غافر\ndeeds\nاپنے دوستوں یا بھائیوں کو قرآن كا كوئى قصہ سنائیں.\nالله كى حمد بیان كریں، اور اس نے آپ کے لئے جانوروں سے مختلف و متنوع فوائد کے حصول کو مسخر کردیا ہے.\nہلاك شده قوموں كے آثار كى تصویروں پر غور وفكر كریں ، پھر اپنى كمیوں اور گناہوں پر الله سے استغفار كریں، كہ كہیں وه عذاب آپ پر نہ آجائے جو ان پر آیا تھا.\nguid\nالله تعالىٰ نے جن رسولوں كى خبریں بیان كى ہیں ان سے عبرت و نصیحت حاصل كریں.\nباطل عوام میں كتنا ہى مقبول ومحبوب بن جائے یقین کیجئے کہ اس کا انجام گھاٹا وخسارہ ہے.\nدین صحیح كى بنیاد وحى صحیح پر ہے نہ كہ بدعات وخرافات پر.\nrefl\nوَلَكُمۡ فِيهَا مَنَٰفِعُ وَلِتَبۡلُغُواْ عَلَيۡهَا حَاجَةٗ فِي صُدُورِكُمۡ وَعَلَيۡهَا وَعَلَى ٱلۡفُلۡكِ تُحۡمَلُونَ ٨٠\nاس آیت میں منافع سے مراد وه فوائد ہیں جو جانوروں کے گوشت كے کھانے کے مقابلے میں حاصل ہوتے ہیں گوشت کھانے کا ذکر اس آیت میں ہے:(ومنها تأكلون)گوشت کھانے کے علاوہ دیگر فوائد میں سےجیسے اس کے اون، دودھ اور قیمت سے فائده اٹھانا، مہروں اور دیتوں میں انہیں عوض كےطور پر استعمال كرنا، انكے چمڑوں سے قبہ وغیره بناكر ان سے فائده اٹھانا، ان پر بیٹھنا اور اسى طرح باڑوں، وادیوں، چشموں اور چراگاہوں میں ان كے آتے جاتے دلکش و خوبصورت منظر سے فائدہ اٹھانا وغیرہ۔ (ابن عاشور: ۲۴؍۲۱۵- ۲۱۶)\nفرمان بارى:(ولكم فيها منافع)كے تحت مویشیوں کے بعض منافع كا ذكر كریں.\nأَفَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ\n(فينظروا) یعنى غور وفكر كى نظر سے دیكھو، نہ كہ غفلت اور بے پرواہى كى نگاہ سے ۔ (السعدى: ۷۴۴)\nجن قوموں کو الله تعالىٰ نے ہلاک کردیا، ان کے کھنڈرات سے گزرنا کب مفید ہے اور كب نقصاندہ؟\nفَلَمَّا جَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ فَرِحُواْ بِمَا عِندَهُم مِّنَ ٱلۡعِلۡمِ\nیہ ان تمام علوم کو شامل ہے جن سے رسولوں کی لائی ہوئی تعلیمات كا معارضہ ومناقضہ كیا گیا، بطور خاص ان میں علم فلسفہ ، اور یونانى منطق شامل ہے جس کے ذریعے بہت سى قرآنى آیات كو رد كیا گیا، دلوں سے ان کا احترام كم كیا گیا، اور قرآن كى یقینى قطعى دلیلوں كو محض لفظی اور یقین سے عاری باور کرایا گیا ، اور قرآنی ٹھوس دلیلوں پر اہل ِباطل كے عقول كو مقدم كیا گیا، اور یہ چیز یقیناً الله كى آیات میں سب سے بڑا الحاد، اور سب سے سنگین معارضہ ہے۔ (السعدى: ۷۴۴)\nبعض علوم مذموم كب ہوجاتےہیں؟ آیت كى روشنى میں اس پر گفتگو كریں.\nفَلَمَّا جَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ فَرِحُواْ بِمَا عِندَهُم مِّنَ ٱلۡعِلۡمِ\nیہاں ضمیر جھٹلانے والى قوموں كى طرف لوٹےگى، اور ان كے علم كى تفسیر کی مختلف وجوہات بیان کی گئی ہے: پہلى وجہ: ان كا یہ عقیده تھا كہ وه دوباره اٹھائے نہیں جائیں گے او ر انكا حساب وكتاب نہیں ہوگا۔ دوسرى وجہ: اس سے دنیاوى مفادو منافع کا علم اور دنیا کمانے كے مختلف ذرائع كا علم مراد ہے۔ تیسرى وجہ: ان فلاسفہ كا علم مراد ہے جو علوم شریعت كو حقیر سمجھتےتھے۔ (ابن جزى: ۲؍۲۸۶)\nاس آیت سے پتہ چلتا ہے كہ بعض علوم ایسے بھى ہوتےہیں جو صاحب علم كے لئے وبال جان بن جاتےہیں، اس كى مثالیں ذكر كیجئے.\nفَلَمَّا جَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ فَرِحُواْ بِمَا عِندَهُم مِّنَ ٱلۡعِلۡمِ\nان كے خود ساختہ مزعومات اور ان کے باطل گمان کو علم كہاگیا ہے ورنہ یہ تو حقیقت میں سراسر جہالت ہے۔ (القرطبى: ۱۸؍۵۵)\nان منکرین اور جھٹلانے والوں كےپاس جو ہے كیا اسے علم كہاجائےگا؟\nفَلَمَّا رَأَوۡاْ بَأۡسَنَا قَالُوٓاْ ءَامَنَّا بِٱللَّهِ وَحۡدَهُۥ وَكَفَرۡنَا بِمَا كُنَّا بِهِۦ مُشۡرِكِينَ ٨٤\nیہاں ان لوگوں كا بیان ہے جو عذاب دیكھ كر ایمان لائے تھے، جس سے ان کا كوئى فائده نہیں ہوا۔ اسے ذكر كركے عربوں كو جلدى ایمان لانے پر ابھارا گیا ہے، اور تاخیر پر خوف دلایا گیا ہے كہ کہیں ایسا نہ ہو کہ عذاب آجائے پھر اس وقت ان كا توبہ ان کے كچھ كام نہ آئے گا۔ (ابن عطیہ: ۴؍۵۷۲)\nكفار قریش كو یہ بتلانے کا كیا فائده ہے كہ ان سےپہلے والے عذاب آنے كے وقت ایمان لائے اور اس سے انہیں كچھ فائده نہیں پہونچا؟\nفَلَمۡ يَكُ يَنفَعُهُمۡ إِيمَٰنُهُمۡ لَمَّا رَأَوۡاْ بَأۡسَنَاۖ سُنَّتَ ٱللَّهِ ٱلَّتِي قَدۡ خَلَتۡ فِي عِبَادِهِۦۖ\nیعنى كافروں كے تعلق سے الله كى یہ سنت رہى ہے كہ عذاب دیكھنے كےبعد ان كا ایمان فائده نہیں پہنچاتا... اورضرورى علم حاصل ہونے نیز عذاب دیكھنے كےبعد توبہ كچھ كام نہیں آئےگا۔ (القرطبى: ۱۸؍۳۸۶)\nاس آیت میں مخلوقات كےتعلق سے اللہ کی کیا سنت رہی ہے اسے بیان كریں.\nwords\nقُضِيَ بِالحَقِّحق كے ساتھ فيصله هوا(رسولوں اور ان كے جھٹلانے والوں كے مابين ).\nحَاجَةً فِي صُدُورِكُمكوئي ايسا كام جس كا تم اهتمام كرتے هو.\nفَمَا أَغنَى عَنهُمپس وه اسے نه بچا سكے.\nوَحَاقَاور گھير ليا.\nبَأسَنَاهمارا عذاب.\nخَلَتگزر گئے."],[477,"§فصلت\ndeeds\nالله كےسامنے گڑگڑائیے كہ آپ كے دل كی اصلاح فرمادے.\nنبی پاک صلی اللہ علیہ وسلم کی اتباع کرتے ہوئے آج زیاده سے زیاده استغفار كیجئے وہ دن میں سو سے زیاده بار استغفار كرتےتھے.\nاپنے مال سے كچھ صدقہ كریں اور فتنۂ مال کے شر سے اللہ کی پناہ مانگیں.\nguid\nہر مسلمان جو كلام الله كو سمجھنا چاہتا ہے اس پر عربى زبان كا سیكھنا بہت اہم ہے.\nجب لوگوں كو وعظ كریں یا كسى كو نصیحت كریں تو اپنے كلام میں ترغیب وترہیب دونوں پہلو شامل رکھیں.\nراحت اسى وقت ملےگى جب آپ الله كى اطاعت اور كثرت استغفار کی عادت ڈالیں گے جیسا کہ اللہ تعالیٰ نے اس کا حکم آپ کو دیا ہے.\nrefl\nتَنزِيلٞ مِّنَ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ ٢\nالله تعالىٰ كى سب سے بڑى رحمت اس کتاب یعنی قرآن مجید کااتارنا ہے كہ جس كےذریعے علم وہدایت ، نور وشفا ، رحمت اور بہت سارى خیر كى چیزیں حاصل ہوئیں جو بندوں پر اسكى طرف سے بہت بڑى نعمتیں ہیں۔ (السعدى: ۷۴۴)\nاس امت پر رحمت الہى كے عظیم مظاہر ذكر كریں.\nكِتَٰبٞ فُصِّلَتۡ ءَايَٰتُهُۥ\nیعنى اس كى سارى قسموں كو علاحده علاحده تفصیل سے بیان كردیا گیا ہے، اور اس سے یہ لازم آتاہے كہ قرآن میں ہر چیز کا مکمل بیان ہے، اور ہر شیئ کو واضح کیاگیا ہے اورتمام حقائق کو الگ الگ بیان کیا گیا ہے۔ (السعدى: ۷۴۴)\nفرمان بارى: (فُصِّلت آياته) سے ہم كیا فائده حاصل كرتےہیں؟\nبَشِيرٗا وَنَذِيرٗا فَأَعۡرَضَ أَكۡثَرُهُمۡ فَهُمۡ لَا يَسۡمَعُونَ ٤\nیہاں اس سماع كى نفى ہے جو قابل اعتبار اور نفع بخش ہو۔ (ابن عطیہ: ۵؍۴)\nیہاں كافروں كے كس سماع كى نفى كى گئى ہے؟\nوَقَالُواْ قُلُوبُنَا فِيٓ أَكِنَّةٖ مِّمَّا تَدۡعُونَآ إِلَيۡهِ وَفِيٓ ءَاذَانِنَا وَقۡرٞ وَمِنۢ بَيۡنِنَا وَبَيۡنِكَ حِجَابٞ فَٱعۡمَلۡ إِنَّنَا عَٰمِلُونَ ٥\nیہاں حجاب سے مراد دین کا اختلاف ہے؛ كیونكہ انكا دین بتوں كى عبادت ہے اور محمد صلی اللہ علیہ وسلم کا دین الله وحده لاشریك كى عبادت كا نام ہے، یہى وه حجاب ہے جس كےبارےمیں ان كا گمان تھا كہ ان كے اور نبى صلی اللہ علیہ وسلم كے درمیان حائل ہے۔ (الطبرى: ۲۱؍۴۲۹)\nكافروں كا گمان تھا كہ جن رسولوں كو ان كى طرف بھیجا گیا اُن كے اور اِن كے درمیان ایك حجاب ہے ، اس سے كیا مراد ہے؟\nقُلۡ إِنَّمَآ أَنَا۠ بَشَرٞ مِّثۡلُكُمۡ يُوحَىٰٓ إِلَيَّ أَنَّمَآ إِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞ فَٱسۡتَقِيمُوٓاْ إِلَيۡهِ وَٱسۡتَغۡفِرُوهُۗ وَوَيۡلٞ لِّلۡمُشۡرِكِينَ ٦\nیعنى میں كوئى فرشتہ نہیں بلكہ آدم كى اولاد ہوں۔ حسن نے كہا: الله تعالىٰ نے آپ كو یہاں تواضع ا ور خاكسارى سكھلائى ہے۔ (القرطبى: ۱۸؍۳۹۲)\nتواضح اور خاكسارى كى اہمیت پر آیت كا معنى كیسے دلالت كرتاہے ، وضاحت كریں.\nٱلَّذِينَ لَا يُؤۡتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلۡأٓخِرَةِ هُمۡ كَٰفِرُونَ ٧\nاگر آپ اعتراض كریں كہ مشركین كے دوسرے تمام اوصاف كو چھوڑ كر كفر آخرت كےساتھ منع زكاة كو ہى كیوں خصوصی طور پر ذکر كیا گیا؟ تو میں كہوں گا: چونكہ انسان كےنزدیك سب سے محبوب چیز اسكا مال ہے، اور یہ اسكى روح جیسا ہے، چنانچہ جب وه الله كى راه میں اسے خرچ كرتاہے تو یہ اسكے ثبات قدمى، استقامت، صدق نیت اور باطنى پاكیزگى کی بہت بڑى دلیل ہوتى ہے، غور كریں الله كے اس قول پر: ﴿وَمَثَلُ ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمُ ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِ وَتَثۡبِيتٗا مِّنۡ أَنفُسِهِمۡ﴾ [البقرة: ۲۶۵]یعنى وہ لوگ خود کو ثابت قدم رکھتے ہیں اور مال كو خرچ كركے ثبات قدمی پر دلیل پیش کرتےہیں۔(القرطبى: ۱۸؍۳۹۳)\nكفر آخرت كےساتھ منع زكاة كاذكر كیوں كیاگیا؟\n۞قُلۡ أَئِنَّكُمۡ لَتَكۡفُرُونَ بِٱلَّذِي خَلَقَ ٱلۡأَرۡضَ فِي يَوۡمَيۡنِ وَتَجۡعَلُونَ لَهُۥٓ أَندَادٗاۚ ذَٰلِكَ رَبُّ ٱلۡعَٰلَمِينَ ٩ وَجَعَلَ فِيهَا رَوَٰسِيَ مِن فَوۡقِهَا وَبَٰرَكَ فِيهَا وَقَدَّرَ فِيهَآ أَقۡوَٰتَهَا فِيٓ أَرۡبَعَةِ أَيَّامٖ سَوَآءٗ لِّلسَّآئِلِينَ ١٠\nباوجودیكہ الله تعالىٰ ان تمام مخلوقات كو ایك ہى لمحے میں پیدا كرسكتاہے پھر بھى انہیں ایك خاص مدت میں پیدا كیا ، اس كى حكمت یہ ہے كہ اپنے بندوں كو اس كےذریعےتمام معاملات و امور میں غور وفكر كرنے اور عجلت نہ كرنے كى عادت سكھائے۔ (ابن عطیہ: ۵؍۵)\nباوجودیكہ الله تعالىٰ زمین وآسمان اور ان كےبیچ كى تمام مخلوقات كو ایك ہى لمحے میں پیدا كرسكتا تھا پھر بھى انہیں ایك خاص مدت میں پیدا كرنے كى كیا حكمت ہے؟\nwords\nفُصِّلَتواضح كردي گئيں اس كي آيات.\nأَكِنَّةٍپردے۔ هماري دعوت كي راه ميں ركاوٹ.\nوَقرٌبوجھ / بهرا پن.\nفَاستَقِيمُوا إِلَيهِاس تك رسائي كي راه پر چلو.\nغَيرُ مَمنُونٍنه ختم هونے والا۔ نه منقطع هونے والا.\nأَندَادًاشريك / هم پله.\nرَوَاسِيَپهاڑ.\nأَقوَاتَهَاان كا رزق."],[478,"§فصلت\ndeeds\nپچھلى قوموں میں سے كسى قوم كى ہلاکت كے اسباب خود پڑھیں یا ان کے بارے میں کسی سے سوال كریں.\nغرور وگھمنڈ اور تكبر سے الله كى پناه مانگیں.\nجب آندھى آتےدیكھیں تو یہ دعا پڑھیں: (اَللّٰهُمَّ إِنِّيْ أَسْئَلُكَ خَيْرَهَا وَخَيْرَ مَا فِيْهَا وَخَيْرَ مَا أُرْسِلَتْ بِهٖ وَأَعُوذُ بِكَ مِنْ شَرِّهَا وَشَرِّ مَا فِيْهَا وَشَرِّ مَا أُرْسِلَتْ بِهٖ):اے اللہ! میں تجھ سے اس ہوا (آندھی) کی بھلائی کا سوال کرتا ہوں، اس بھلائی کا سوال کرتا ہوں جو اس میں ہے اور اس بھلائی کا سوال کرتا ہوں جسے دے کر یہ بھیجی گئی ہے.\nguid\nالله كى اطاعت سے منہ پھیرنے اور اعراض كرنے سےبچیں كہ یہى عذاب الہى كے نزول كا سبب ہے.\nبغیر گناه كوئى مصیبت نہیں آتى.\nگنہ گار كو سزا دینے سے پہلے اسے اس کے گناه كےبارے میں بتا دیں جس كى وجہ سے وه سزا كا مستحق ٹھہرا ہے.\nrefl\nإِذۡ جَآءَتۡهُمُ ٱلرُّسُلُ مِنۢ بَيۡنِ أَيۡدِيهِمۡ وَمِنۡ خَلۡفِهِمۡ أَلَّا تَعۡبُدُوٓاْ إِلَّا ٱللَّهَۖ قَالُواْ لَوۡ شَآءَ رَبُّنَا لَأَنزَلَ مَلَٰٓئِكَةٗ فَإِنَّا بِمَآ أُرۡسِلۡتُم بِهِۦ كَٰفِرُونَ ١٤\n(من بين أيديهم ومن خلفهم) آگےپیچھے سے رسول آئے ، یہ ایك تمثیل ہے كہ ہر رسول ان كى ہدایت كیلئے كس قدر حریص تھا، كہ دین كو ان تك پہنچانے كیلئے انہیں جو بھى وسیلہ میسر آیا سب استعمال كئے،اسی کو بطور مثال ان کے سامنے اور پیچھے سے آنے سے تشبیہ دی گئی یعنی کبھی تو ان کے سامنے سے آئے، اور کبھی توپیچھے سے آکر تبلیغ کئے ، كسى سمت كو نہیں چھوڑے، جس طرح كہ جب كوئى شحص كسى چیز كے حصول كیلئے حریص ہوتا ہے تو وه اس کو طلب کرتا ہے اور بار بار اسكے پیچھے پڑتا ہے، اور اسكے وجودوامکان كى سارى جگہوں كى تلاش میں رہتاہے۔ (ابن عاشور: ۲۴؍۲۵۳)\nآیت كریمہ كى روشنى میں رسولوں كى تبلیغ دین پر حرص کو بیان كریں.\nقَالُواْ لَوۡ شَآءَ رَبُّنَا لَأَنزَلَ مَلَٰٓئِكَةٗ فَإِنَّا بِمَآ أُرۡسِلۡتُم بِهِۦ كَٰفِرُونَ ١٤\nیہ ایک قدیم شبہ ہے، جو منکرین رسالت كے یہاں نسل در نسل چلا آرہا ہے اور یہ انتہائی بودا شبہ ہے؛ كیونكہ رسالت كیلئے رسول کا فرشتہ ہونا شرط نہیں ہے ، بلكہ رسالت كى شرط یہى ہے كہ رسول جو كچھ لیكر آئے وه اس كى سچائى پر دلالت كرے، اب اگر ان كے پاس استطاعت ہے تو رسول کی سچائى پر عقلى یا شرعى نقد کریں، اور یہ چیزیں ان کے لئے محال ہے۔ (السعدى: ۷۴۶)\nآیت كى روشنى میں تمام كافروں کے شبہات کا متشابہ ہوناواضح كیجئے.\nفَأَمَّا عَادٞ فَٱسۡتَكۡبَرُواْ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَقَالُواْ مَنۡ أَشَدُّ مِنَّا قُوَّةًۖ\nجب الله تعالىٰ نے انہیں عذاب كى دھمكى دى تو وه اپنى جسموں سے دھوكہ كھا گئے اور كہا: ہم اپنى قوت سے خود عذاب ٹالنے كى طاقت ركھتےہیں، ایسا انہوں نے اس لئے كہا كیونكہ وه لمبے تڑنگے بھارى بھركم جسم والے تھے۔ (القرطبى: ۱۸؍۴۰۱)\nالله كا فیصلہ آنے كے وقت قوم ہودکس چیز سے دھوكہ میں مبتلا ہوگئی؟ اور كیا اس نے انہیں كچھ نفع پہونچایا؟\nوَأَمَّا ثَمُودُ فَهَدَيۡنَٰهُمۡ\nگرچہ تما م ہلاك شده قوموں پر حجت قائم كردى گئى تھى اور ان كے سامنے واضح نشانیاں آگئى تھیں ، لیكن یہاں قوم ثمود کی ہدایت کی نشانی کو صراحت کے ساتھ ذکرکیاگیا، كیونكہ ان کی نشانی بہت واضح نشانى تھى، ان كے چھوٹے بڑے، مردوں اور عورتوں سب نے اسے دیكھا، اور یہ ایك روشن نشانى تھى، اسى لئے قوم ثمود کا خصوصی ذکرمزید ہدایت و بیان کےساتھ کیا۔ (السعدى: ۷۴۷)\nہدایت كا ذكر یہاں خصوصى طور پر قوم ثمود كیلئے كیوں آیا ہے جبكہ الله نے تمام انسانیت كو ہدایت كى طرف بلایا ہے؟\nوَأَمَّا ثَمُودُ فَهَدَيۡنَٰهُمۡ فَٱسۡتَحَبُّواْ ٱلۡعَمَىٰ عَلَى ٱلۡهُدَىٰ\nیہ ایسے ہى ہے جیسے اسلامى شریعت جو كہ یہود ونصارى كیلئے بالكل واضح ہے جو ہمارے ساتھ میں رہتےہیں، لیكن اس سے اعراض كرتےہیں اور اس سے دوسروں كو بھى روكتے ہیں، یہى ان كا ہدایت پر گمراہى كو بہتر سمجھنا اور اسے ترجیح دینا ہے۔ (ابن عطیہ: ۵؍۱۰)\nآیت كےاندر ہدایت پر گمراہى كو بہتر سمجھنے اور اسے ترجیح دینے سے كیا مراد ہے؟\nوَيَوۡمَ يُحۡشَرُ أَعۡدَآءُ ٱللَّهِ إِلَى ٱلنَّارِ فَهُمۡ يُوزَعُونَ ١٩\nیعنى ان لوگوں كو ہكا كر جہنم كى طرف ڈھكیل دیا جائےگا، قتاده اور سدى نے كہا: شروع سے آخر تك سب كو ایك ساتھ جمع كیا جائےگا۔ ابو الاحوص نے كہا: جب سارى تعداد پورى ہوجائےگى تو سب سے پہلے ان لوگوں سے ابتداء ہوگى جو سب سے بڑےمجرم ہوں گے۔ (القرطبى: ۱۸؍۴۰۵)\nالله كى پناه! الله کے دشمنوں كو جہنم كى طرف كیسے ہكا كر لے جایا جائےگا؟\nحَتَّىٰٓ إِذَا مَا جَآءُوهَا شَهِدَ عَلَيۡهِمۡ سَمۡعُهُمۡ وَأَبۡصَٰرُهُمۡ وَجُلُودُهُم بِمَا كَانُواْ يَعۡمَلُونَ ٢٠\nمذكوره صرف تین ہى اعضاء كا خصوصى طور پر ذكر كیا گیا كیونكہ گناه اكثر انہیں سے یا انہیں كى وجہ سے انجام پاتا ہے۔ (السعدى: ۷۴۷)\nدوسرے باقى اعضا كو چھوڑ كر انہیں تینوں كا خصوصى ذكر كیوں كیا گیا؟\nwords\nفَقَضَاهُنَّپس اس نے ان كو پيدا كيا.\nبِمَصَابِيحَروشن ستارے.\nصَاعِقَةًخوفناك عذاب.\nصَرصَرًابهت سخت ٹھنڈا؛ اوراونچي آواز والا.\nنَحِسَاتٍمنحوس / بدشگوني.\nالهُونِذليل كرنے والا.\nيُوزَعُونَان كے پهلے كو آخري پر لوٹايا جائے گا(تقسيم كئے جائيں گے)."],[479,"§فصلت\ndeeds\nجو آپ كیلئے برے كاموں كو مزین كركےپیش كرے اس کوپہچانیں اور اس كےساتھ اٹھنے بیٹھنے سے پرہیز كریں.\nالله سے گڑگڑاكر دعا كریں كہ آپ كو نیك ساتھى عطاكرے اور برے ساتھى سےنجات دے.\nآیات میں غور وفكر كرنےكیلئے كسى اچھے قارى كى آواز میں قرآن سنیں.\nguid\nالله كےساتھ حسن ظن ركھیں اور مشركین کی مخالفت کریں، کیونکہ وہ اللہ سے برا گمان ركھتےہیں.\nكچھ لوگ ایسےہیں جو اطاعت الہى كےراستےپرگامزن ہیں اور كچھ ایسےہیں جو معصیت الہى کی راہ اپنائے ہوئے ہیں.\nاگر متبوع اماموں اور سرداروں كے اوامر الله كے اوامر کے مخالف ہوں تو سمجھ لیں كہ وه خود ہلاك ہوئے اور اپنے پیروكاروں كو بھى ہلاک و برباد کیا.\nrefl\nوَمَا كُنتُمۡ تَسۡتَتِرُونَ أَن يَشۡهَدَ عَلَيۡكُمۡ سَمۡعُكُمۡ وَلَآ أَبۡصَٰرُكُمۡ وَلَا جُلُودُكُمۡ\nاس کے دو مفہوم ہے: پہلا مفہوم: تم اپنے كانوں، اپنى نگاہوں اور اپنى جلد وں سےاپنی بد اعمالیوں کو نہیں چھپا سكتے تھے؛ كیونكہ یہ سب تمہارےساتھ ہمیشہ رہنے والے تھے، ان سےبچنے كا كوئى راستہ نہیں تھا، لہٰذا اب وه اعضا تمہارے خلاف گواہى دے رہے ہیں۔ دوسرا مفہوم: تمہیں اس بات كا كوئى خوف نہیں تھا كہ تمہارےكان، تمہارى نگاہیں اور تمہارے جلد تمہارے خلاف گواہى دیں گے ؛ كیونكہ تم نے ان كى گواہى كى كوئى پرواه نہیں كى اور نہ ہى تمہیں یہ گمان تھا كہ یہ سب تمہارےخلاف گواہى دیں گے۔(ابن جزى: ۲؍۲۹۱)\nفرمان بارى: (تَسْتَتِرُوْنَ) سے كیا مراد ہے؟ اور اس آیت سے كیا فائده ملتا ہے؟\nوَذَٰلِكُمۡ ظَنُّكُمُ ٱلَّذِي ظَنَنتُم بِرَبِّكُمۡ أَرۡدَىٰكُمۡ فَأَصۡبَحۡتُم مِّنَ ٱلۡخَٰسِرِينَ ٢٣\nحسن بصرى نےكہا: كچھ لوگوں كو آرزؤں نے غافل كردیا یہاں تك كہ جب وه دنیا سے گئے تو ان كےپاس كوئى نیكى نہیں تھى، اور انہیں میں سے ایك كہتا ہے: میں اپنے رب كے ساتھ حسن ظن ركھتا ہوں حالانكہ وه جھوٹ بولتا ہے ، اگر وه حسنِ ظن ركھتا تو نیك عمل كرتا۔ (القرطبى: ۱۸؍۴۰۹- ۴۱۰)\nواضح كریں كہ كب الله كےساتھ حسن ظن ركھنا بے محل ہوتا ہے؟\n۞وَقَيَّضۡنَا لَهُمۡ قُرَنَآءَ فَزَيَّنُواْ لَهُم مَّا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡ\nیعنى ہم نے ان كے لئے شیاطین تیار كرركھےہیں ۔ اور كہاگیا: ہم نے ان پر ایسے ساتھى مسلط كر ركھےہیں جو گناہوں كو ان كیلئے مزین كركےپیش كرتےہیں، اور یہ ساتھى جن وشیاطین اور انسانوں میں سے بھى ہوتےہیں۔ (القرطبى: ۱۸؍۴۱۱)\nآیت میں بندے كےساتھ برائى كےارادے كى کونسی ایک علامت ہے؟\nوَقَالَ ٱلَّذِينَ كَفَرُواْ لَا تَسۡمَعُواْ لِهَٰذَا ٱلۡقُرۡءَانِ وَٱلۡغَوۡاْ فِيهِ لَعَلَّكُمۡ تَغۡلِبُونَ ٢٦\nیہى گمراه داعیوں اور باطل پرستوں كا وطیره رہاہے كہ وه حق بولنے والوں اور دلائل سے بات كرنے والوں كا ناطقہ ہر ممكن طریقے سے بند كرنے كى كوشش كرتےہیں ، اور اس كیلئے وه ترغیب وترہیب اور لالچ وخوف ہر حربہ اپناتے ہیں، اور لوگوں كو یہ موقع ہى نہیں دیتے كہ حجت ودلیل كى روشنى میں بحث ومباحثہ كریں اور دلیلِ حق کی طرف رجوع کریں، كیونكہ انہیں پتہ ہوتاہے كہ مد مقابل كى حجت بڑى مضبوط ہے، اسى لئے وه اس پر پرده ڈالنے كى كوشش كرتےہیں اور بہتان وگمراہى كے ذریعے اپنا دفاع كرتےہیں، لیكن جب ان كى مكاریاں اور حیلہ سازیاں جواب دینے لگتى ہیں اور دیكھنے لگتےہیں كہ حق كا ڈنكا لوگوں میں بجنے لگا ہے، تو پھر گالى گلوج اور بیہودگى پر اتر آتےہیں اور شوروشغب كا بھونپو ہاتھ میں تھام لیتےہیں۔(ابن عاشور: ۲۴؍۲۷۷)\nآیت كى روشنى میں حق كو روكنے میں اہل ضلالت كى ایك صفت واضح كریں.\nوَقَالَ ٱلَّذِينَ كَفَرُواْ لَا تَسۡمَعُواْ لِهَٰذَا ٱلۡقُرۡءَانِ وَٱلۡغَوۡاْ فِيهِ لَعَلَّكُمۡ تَغۡلِبُونَ ٢٦\nیہ گواہى ہے خود دشمنوں كى طرف سے ، اور سب سے واضح حق وہى ہے جس كى گواہى خود دشمن دیدے، كیونكہ حق كے مقابلے میں وه اپنے لئے غلبہ كا فیصلہ اسى وقت كررہےہیں جب وه اس حق سے اعراض کریں اور لوگوں كو اس سے موڑنے میں كامیاب ہوجائیں، اور ان كے کلام کا مفہوم مخالف یہ ہے كہ اگر وه تلاوت کلام پاک کے وقت شور و شغب نہ كریں بلکہ اسے بغور سننے لگیں اور اپنے اذہان وقلوب كو اس كى طرف لگا دیں تو ایسى صورت میں وه كبھى غالب نہیں ہوسكتے۔ (۷۴۸)\nآیت میں كافروں كى جانب سے قرآن کے برحق ہونے کی ایک گواہى موجود ہے، اسکی وجہ بیان کیجئے؟\nوَقَالَ ٱلَّذِينَ كَفَرُواْ لَا تَسۡمَعُواْ لِهَٰذَا ٱلۡقُرۡءَانِ وَٱلۡغَوۡاْ فِيهِ لَعَلَّكُمۡ تَغۡلِبُونَ ٢٦\nابن عباس رضی اللہ عنہما نے فرمایا : اس میں شور و شغب پیدا کرو۔ اور وه لوگ ایك دوسرے كو وصیت كرتےتھےكہ جب تم محمد صلی اللہ علیہ وسلم كو قرآن كى تلاوت كرتے دیكھو تو اسكا معارضہ اور سامنا رجزیہ اشعار ، شعر و شاعری اور لغو باتوں سے كرو ۔ امام مجاہد نے كہا: تالى اور سیٹى كےذریعے شور مچاؤ۔ اور ضحاك نے كہا: زیاده بولو كہ ان كى بات خلط ملط ہوجائے۔ (القرطبى: ۴؍۶۵)\nذكر ونصیحت سے فائده اٹھانے سے اہل فساد لوگوں كو روكنے كیلئے كیسے كیسے حربے استعمال كرتےہیں؟ آیت كى روشنى میں ان کے بعض اسالیب بیان كریں.\nوَقَالَ ٱلَّذِينَ كَفَرُواْ رَبَّنَآ أَرِنَا ٱلَّذَيۡنِ أَضَلَّانَا مِنَ ٱلۡجِنِّ وَٱلۡإِنسِ نَجۡعَلۡهُمَا تَحۡتَ أَقۡدَامِنَا لِيَكُونَا مِنَ ٱلۡأَسۡفَلِينَ ٢٩\nپھر الله تعالىٰ نے كافروں كى ان باتوں كا ذكر كیا جنہیں وه قیامت كےدن دوزخ میں جانے كےوقت كہیں گے، کیونکہ جب وه عظیم عذاب كى ہولناكى اور برے ٹھکانے كا مشاہده كریں گے تو انہیں ان لوگوں كى یاد آئےگى جنہوں نے انہیں دنیا میں گمراه كیا تھا، پھر ان پر وه شدید غصہ ہوں گے اور خواہش كریں گے كہ وه بھى سخت سے سخت عذاب میں مبتلا ہوں ، لہذاوه كہیں گے: (ربنا أرنا اللذين أضلانا). (ابن عطیہ: ۵؍۱۴)\nدوزخى ایسا كہنے پر مجبور كیوں ہوں گے كہ وه طلب كرنے لگیں گے كہ انسانوں اور جناتوں میں سے جن لوگوں نے انہیں گمراه كیا تھا وه آج انكے پیروں تلےہوجائیں؟\nwords\nتَستَتِرُونَتم بوقت گناه چھپتے هو.\nمَثوىًٹھكانا.\nيَستَعتِبُواوه مغفرت طلب كريں.\nفَمَا هُم مِنَ المُعتَبِينَان كي طلب قبول نهيں كي جائے گي.\nوَقَيَّضنَاهم نے تيار كرديا."],[480,"§فصلت\ndeeds\nكسى ایسے شخص كو ہدیہ دیں جس سے آپ كى نہ بنتى ہو، پھر دیكھیں یہ ہدیہ آپ دونوں كے دلوں كى كیسے اصلاح كرتا ہے.\nجب بھى آپ كو شیطان كے كچوكےكا احساس ہو اس وقت فوراً الله كى پناه مانگئے.\nاس آیت كى تلاوت كے وقت سجد ۂ تلاوت كریں.\nguid\nمومن كى جس وقت روح نكلتى ہے اسى وقت وه آخرت میں اپنے انجام سے باخبر ہوجاتاہے.\nمومن كیلئے جنت میں ہر وه چیز ہے جو وه چاہے گا اور جو اسكى آنكھوں كو اچھى لگیں گى.\nصبر كى عادت ڈالیں كہ یہ اخلاق حسنہ كى جڑ ہے.\nrefl\nإِنَّ ٱلَّذِينَ قَالُواْ رَبُّنَا ٱللَّهُ ثُمَّ ٱسۡتَقَٰمُواْ تَتَنَزَّلُ عَلَيۡهِمُ ٱلۡمَلَٰٓئِكَةُ\nفرمان بارى: (قالوا ربنا الله ثم استقاموا) نے كمال اسلامى كے دونوں اصل كو جمع كر دیا ہے، چنانچہ فرمان بارى: (قالوا ربنا الله) سے اشاره كمال نفسانى كى طرف ہے ، اور وه معرفت حق ہے ہدایت پانے كیلئے، اور معرفت خیر ہے اس پر عمل كرنے كیلئے... اور فرمان بارى: (ثم استقاموا) سے اعمال صالحہ كى اساس کی طرف اشاره ہے، اور وہ حق پر استقامت ہے۔ (ابن عاشور: ۲۴؍۲۸۳)\nفرمان بارى: (قالوا ربنا الله ثم استقاموا) نے كمال اسلامى كے دونوں اصل كو كیسے جمع كر دیا ہے؟\nإِنَّ ٱلَّذِينَ قَالُواْ رَبُّنَا ٱللَّهُ ثُمَّ ٱسۡتَقَٰمُواْ\nعمر بن خطاب رضی اللہ عنہ نے فرمایا: استقامت یہ ہے كہ تم امر ونہى پر قائم رہو اور لومڑى كى طرح پیترا مت كاٹو۔ اور عثمان بن عفان رضی اللہ عنہ نے فرمایا: الله كیلئے عمل كو خالص كرلو۔ اور على رضی اللہ عنہ نے فرمایا: فرائض كو ادا كرو۔ (البغوى: ۴؍۶۵- ۶۶)\nآیت میں استقامت سے كیا مراد ہے ؟ اس كى حقیقت بیان كریں.\nنَحۡنُ أَوۡلِيَآؤُكُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَفِي ٱلۡأٓخِرَةِۖ\nیعنى جو فرشتے ان کے پاس آتے ہیں وہى انہیں یہ بشارت دیتےہیں كہ (ہم تمہارے ساتھى ہیں) مجاہد نے كہا: یعنى ہم یہاں بھى ویسے ہى تمہارے قرین ساتھى رہیں گے جیسے دنیا میں تھے، پھر قیامت كےدن كہیں گے كہ جب تك تم جنت میں چلےنہیں جاتے ہم ساتھ نہیں چھوڑیں گے۔ (القرطبى: ۱۸؍۴۱۸)\nآیت میں ایك فائده مذكور ہے جسے مومنین فرشتوں سےاٹھا سكتےہیں، بتائیے وه كیا ہے؟\nوَمَنْ أَحْسَنُ قَوۡلٗا مِّمَّن دَعَآ إِلَى ٱللَّهِ وَعَمِلَ صَٰلِحٗا وَقَالَ إِنَّنِي مِنَ ٱلۡمُسۡلِمِينَ ٣٣\nیعنى(سب سے زیادہ اچھی بات والا وہ شخص ہے جو) الله كےبندوں كو اللہ کی طرف بلائے ، اور ساتھ ہى خود بھى ہدایت پر ہو، ایسى صورت میں اسكا نفع خوداسكے لئے بھى ہے اور دوسروں كیلئےبھى ، یعنى یہ فائده لازم اور متعدى دونوں ہے، اور ایسا شخص ان لوگوں میں سے نہیں ہے جودوسروں كو بھلائى كا حكم كرتےہیں اور خودبھلائی پر عمل نہیں كرتے، اور برائى سے دوسروں كو منع كرتےہیں اور خودبرائی سے نہیں بچتے، بلكہ یہ لوگ بھلا ئى بھى كرتےہیں اور برائى سے دور رہتےہیں، اور مخلوق كو انكے خالق كى طرف بلاتےہیں۔ (ابن كثیر: ۴؍۱۰۲)\nایك سچے داعى كی علامت كیا ہے؟\nوَمَا يُلَقَّىٰهَآ إِلَّا ٱلَّذِينَ صَبَرُواْ وَمَا يُلَقَّىٰهَآ إِلَّا ذُو حَظٍّ عَظِيمٍ٣٥\nیعنى اس عمده خصلت(برائی کو اچھائی کے ساتھ ٹالنے) كى توفیق انہیں كو ملتى ہے جو تكلیف ده چیزوں پر صبر كرتےہیں، اور اپنے نفسوں كو اللہ کی پسندیدہ چیزوں پر مجبور كرتےہیں ، كیونكہ نفس انسانى كى یہ فطرت ہے كہ برائى كا بدلہ برائى سے دے اور اسے معاف نہ كرے، پھر وہ احسان کا معاملہ كیسے كرسكتى ہے؟ لیکن جب انسان اپنے نفس كو صبر دلا لیتاہے، اور اپنے رب كا حكم بجا لاتا ہے، عظیم ثواب سے آگاه ہوتا ہے، اور یہ جانتاہے كہ برائى كا بدلہ برائی سے لینے سے اسے كچھ بھى فائده دینے والا نہیں ہے، بلکہ عداوت میں مزید شدت ہى پیدا ہوگى، نیز یہ جانتا ہے كہ اس پر احسان کرنے سے اس كى قدر ومنزلت کم نہیں ہوگی بلكہ وه جانتا ہے كہ جو الله كیلئے تواضع اپناتا ہے الله اس كا مقام بلند كرتا ہے، تو ایسى صورت میں برائی کا بدلہ اچھائی سے دینے کامعاملہ اس كےلئے آسان ہوجاتا ہے اور ایسے نیك كام وه لذت اور حلاوت محسوس کرتے ہوئے كرتا رہتاہے۔ (السعدى: ۷۴۹)\nایسى حالت صرف صبر كرنے والوں اور بڑے نصیب والوں كیلئے ہى كیوں ثابت ہے؟\nوَمَا يُلَقَّىٰهَآ إِلَّا ٱلَّذِينَ صَبَرُواْ وَمَا يُلَقَّىٰهَآ إِلَّا ذُو حَظٍّ عَظِيمٍ٣٥\n(عمدہ خصلت کی توفیق سب کونہیں ملتی) كیونكہ یہ خاص بندوں كى خصلتیں ہیں جن كے ذریعے بنده دنیا وآخرت دونوں جگہ بلندى پاتاہے ، اور یہ مكارم اخلاق كے عظیم خصلتوں میں سے ہے۔ (السعدى: ۷۴۹)\nآیت میں الله كے خاص بندوں كى ایك علامت بیان کی گئی ہیں، بتائیے وه كیا ہے؟\nوَإِمَّا يَنْزَغَنَّكَ مِنَ الشَّيْطَانِ نَزْغٌ فَاسْتَعِذْ بِاللَّهِ إِنَّهُ هُوَ السَّمِيعُ الْعَلِيمُ٣٦\nپہلےجب الله تعالىٰ نے انسانی دشمنوں كےساتھ کس ہتھیار سے مقابلہ کیاجائے گا، اس كا ذكر كیا یعنی كہ ان كى برائى كا بدلہ احسان سے دیا جائے ،تو اس كے بعد اللہ تعالیٰ جنی دشمنوں کو بھگانے کا طریقہ بیان كررہاہے اور وہ یہ ہے کہ ایسى صورت میں جنات كے شر سے الله كى پناه اور حمایت مانگو، ارشاد بارى ہے: (وإما ينزغنك من الشيطان نزغ) یعنى كسى بھى وقت تم شیطان كى طرف سے كسى كچوكے كا احساس كرو ، یعنى اس كے وسوسوں كا، اسكى طرف سے برائیوں كے مزین كرنے كا، خیر سے كاہل بنانےكا، اور كسى گناه كے كرنے اور اسكى بات ماننے کا احساس کرو ۔ (فاستعذ بالله) تو ایسى صورت میں اپنی محتاجی کا اظہار کرتے ہوئے الله سے مانگو كہ وہ تمہیں پناه دےاور اسكے شر سے محفوظ ركھے۔ (السعدى: ۷۵۰)\nہم جناتوں میں سے دشمنوں كو كیسے دفع كرسكتے ہیں؟\nwords\nاستَقَامُواوه علم و عمل كے لحاظ سے حق پر ثابت قدم رهے.\nوَلِيٌّ حَمِيمٌبهت هي مهربان و شفيق دوست.\nوَمَا يُلَقَّاهَااور اس كي توفيق نهيں دي جائے گي.\nيَنزَغَنَّكَوه تمهارے نفس ميں وسوسه ڈالے.\nفَاستَعِذ بِاللهِالله كي پناه مانگيں اعوذ بالله من الشيطان الرجيم پڑھيں.\nلاَ يَسأَمُونَوه اكتاتے نهيں؛ تھكتے نهيں."],[481,"§فصلت\ndeeds\nدعا كریں كہ الله تعالىٰ آپ كے دل كوایمان سے معموروزندہ كردے جیسے پانى كےذریعے مرده زمین كو زنده كردیتاہے.\nایك پیغام بھیجیں جس میں یہ خوشخبرى دیں كہ اصلاح احوال اور تكلیفوں كے دور كرنے سے الله كى رحمت قریب ہوتى ہے.\nتكلیف كى جگہ اپنا ہاتھ ركھیں اور قرآن میں سے جو میسر ہو اسے پڑھیں كہ اس میں شفا ء ہے.\nguid\nایسى رحمت سے مایوسى نہیں ہونى چاہئے جس كےذریعے الله تعالىٰ ملكوں كے احوال درست كرتاہے ، فقر وخوف اور جنگ دور كرتاہے.\nكافروں ، منافقوں اور بددینوں كے شبہات قرآن اور دین كے تعلق سے مرور زمانہ كےساتھ بھی ہمیشہ ایك ہى جیسے رہتےہیں.\nاہل ایمان كیلئے قرآن شفااور دوا ہے، جبكہ اہل كفر اور اہل نفاق كیلئے ہلاکت کا سبب ہے.\nrefl\nإِنَّ ٱلَّذِينَ يُلۡحِدُونَ فِيٓ ءَايَٰتِنَا لَا يَخۡفَوۡنَ عَلَيۡنَآۗ\nاس میں سخت وعید اورزبردست ڈانٹ پھٹكار ہے، یعنى الله تعالىٰ اسے اچھى طرح جانتا ہے جو اسكى آیتوں، اسكے اسماء وصفات میں الحاد كرتےہیں اور ان سے اعراض و انحراف کرتے ہیں، اور وه عنقریب اس كى وجہ سے انہیں عذاب وسزا سے دوچار كرےگا۔ (ابن كثیر: ۴؍۱۰۴)\nان ملحدین كےبارے میں الله نے جو یہ خبر دى كہ وه اس سے اوجھل نہیں ہیں ، اس سے كیا مراد ہے؟\nإِنَّ ٱلَّذِينَ كَفَرُواْ بِٱلذِّكۡرِ لَمَّا جَآءَهُمۡۖ وَإِنَّهُۥ لَكِتَٰبٌ عَزِيزٞ ٤١\nالله تعالىٰ نے كتاب كو عزت كے وصف سے یاد كیا ہے؛ كیونكہ یہ اپنے معانى كى صحت كےاعتبار سے طعن وتشنیع ، اور كسى بھى معارضے سے محفوظ ہےاور اس کی حفاظت الله کے ذمے ہے۔ (ابن عطیہ: ۵؍۱۹)\nالله تعالىٰ نے كتاب كو عزت كے وصف سے یاد كیا ہے، اس كا فائده واضح كریں.\nمَّا يُقَالُ لَكَ إِلَّا مَا قَدۡ قِيلَ لِلرُّسُلِ مِن قَبۡلِكَۚ إِنَّ رَبَّكَ لَذُو مَغۡفِرَةٖ وَذُو عِقَابٍ أَلِيمٖ ٤٣\nسزا كو یہاں دوسرے كسى وصف كو چھوڑ كر (أليم) یعنى دردناك سے متصف كیا ؛ اس بات كى طرف اشاره كرنے كیلئے كہ انہیں جس گناہ کی سزا دی گئی ہے ان کے لئے یہی وصف مناسب ہے ؛كیونكہ انہوں نے نبى كریم صلی اللہ علیہ وسلم كى ذات كو تكلیف دى ہے آپ كى نافرمانى كركے اور آپكو مختلف طرح سے ستا كر۔ (ابن عاشور: ۴؍۳۱۱)\nآیت كریمہ میں (عِقَاب)سزا كیلئے(أليم) دردناك كى صفت كیوں لائى گئى ہے؟\nإِنَّ رَبَّكَ لَذُو مَغۡفِرَةٖ وَذُو عِقَابٍ أَلِيمٖ ٤٣\nاگر الله كى معافى اور اسكا درگزر كرنا نہ ہوتا تو كوئى بھى سكون كى زندگى نہ جى پاتا ، اور اگر اس كى طرف سے وعید اور سزا نہ ہوتى تو ہر كوئى اللہ کی معافی پر بھروسہ کرکے بیٹھ جاتا۔ (ابن كثیر: ۴؍۱۰۴)\nبہت سارى آیتوں میں ایك ہى ساتھ مغفرت اور سزا كا ذكر كیوں كیا گیا ہے جیسے كہ اس آیت میں بھی وہی اسلوب ہے؟\nقُلۡ هُوَ لِلَّذِينَ ءَامَنُواْ هُدٗى وَشِفَآءٞۚ\nالله تعالىٰ نے باخبر كیا كہ قرآن شك وشبہ اور تكلیفوں سے ہر اس شخص كیلئے ہدایت اور شفا ہے جو اس پر ایمان لائے۔(القرطبى: ۱۸؍۴۳۱)\nقرآن كى ہدایت اور اسكى شفا سے كون فائده اٹھا سكتاہے؟\nوَٱلَّذِينَ لَا يُؤۡمِنُونَ فِيٓ ءَاذَانِهِمۡ وَقۡرٞ وَهُوَ عَلَيۡهِمۡ عَمًىۚ أُوْلَٰٓئِكَ يُنَادَوۡنَ مِن مَّكَانِۢ بَعِيدٖ ٤٤\nیعنى وه (جو ایمان نہیں لاتے) نہ سنتےہیں اور نہ سمجھتےہیں، جس طرح كہ دور سے پكارا جانے والا نہ تو سنتا ہے اور نہ ہى كچھ سمجھ پاتاہے، یہ مثال ہے ان لوگوں كى جو وعظ ونصیحت سننے كے باوجود بھى اس سے كچھ فائده نہیں اٹھاتےہیں ، گویا كہ انہیں كسى دور جگہ سے پكارا جارہاہوجہاں سے انہیں سنائی نہیں دے رہا ہو۔ (البغوى: ۴؍۷۰)\nاس مثال (انہیں دور جگہ سے پكارا جا رہا ہے) سے قرآن كا كیا مقصد ہے؟\nوَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ فَٱخۡتُلِفَ فِيهِۚ وَلَوۡلَا كَلِمَةٞ سَبَقَتۡ مِن رَّبِّكَ لَقُضِيَ بَيۡنَهُمۡۚ وَإِنَّهُمۡ لَفِي شَكّٖ مِّنۡهُ مُرِيبٖ ٤٥\nالله فرمارہاہے كہ ان میں جو فریق باطل پر ہے وه اپنى كہى ہوئى باتوں میں(لَفِيْ شَكٍّ) شك وشبہے میں ہے، یعنی وه خود اپنى باتوں میں شك كررہےہیں (مُرِيْبٍ) اور اللہ تعالیٰ فرماتا ہے کہ اس کتاب کے سلسلہ میں ان کی کہی ہوئی باتیں انہیں (یعنی خود ان کو یا غیروں کو) شک و شبہ میں ڈال رہی ہیں کیونکہ انہوں نے بغیر تحقیق و ثبوت كےاور گمان كى بنیاد پر باتیں كہى ہیں۔(الطبرى: ۲۱؍۴۸۷)\nقرآن كریم كےتعلق سے كافر جو بات كہتےہیں انہیں اس پر یقین كیوں نہیں ہوتا؟\nwords\nاهتَزَّتنباتات حركت ميں آگئي.\nوَرَبَتوه پھول گئي؛ بلند هو گئي.\nيُلحِدُونَوه حق سے مائل هوضشتے هيں.\nوَقرٌگونگا پن / بوجھ.\nمُرِيبٍبهت سخت شك والا."],[482,"§فصلت\ndeeds\nاللہ تعالىٰ سے اس کے کشادہ رزق میں سے مانگئے ، اور اس سے یہ طلب کیجئے کہ وہ آپ کو علم نافع سکھائے.\nقیامت سے متعلق بعض آیات واحادیث کا مطالعہ کیجئے.\nاللہ تعالىٰ سے دعا کیجئے کہ وہ آپ پر چھائے غم کے بادل چھانٹ دے.\nguid\nبروز قیامت ہر -غیر اللہ کو- پکارنے والا اس سے جدا ہوجائیگا جسے وہ -دنیا میں- پکارا کرتا تھا، اور ہر ایک دوسرے سے برأت کا اظہار کرنے لگے گا.\nانسان کی کمزوری کا عالم یہ ہے کہ وہ اپنی عقل اور اپنے تصورات تک میں کمزور وناتواں ہے.\nانسان ایمان کے بغیر گمراہ ترین مخلوقات میں سے ہے.\nrefl\nلَّا يَسۡـَٔمُ ٱلۡإِنسَٰنُ مِن دُعَآءِ ٱلۡخَيۡرِ وَإِن مَّسَّهُ ٱلشَّرُّ فَيَـُٔوسٞ قَنُوطٞ ٤٩\nخیر اور شر سے قطع نظر یہ انسان کی اپنی طبیعت اور اسکی ذات کے بارے میں خبر د ی گئی ہے، گویا انسان ایسے ہی واقع ہوا ہے، ہاں وہ شخص اس سے مستثنى ہے جسے اللہ تعالىٰ -نقص وکمزوری کی- اس حالت سے کمال کی حالت تک پہنچا دے۔ (السعدی : ۷۵۲)\nآپ اپنے جسم و دل دونوں اعتبار سے کمزور ہیں، اسے اس آیت کی روشنی میں واضح کیجئے، نیز اس کے علاج کا طریقہ بھی بتایئے؟\nلَّا يَسۡـَٔمُ ٱلۡإِنسَٰنُ مِن دُعَآءِ ٱلۡخَيۡرِ وَإِن مَّسَّهُ ٱلشَّرُّ فَيَـُٔوسٞ قَنُوطٞ ٤٩ وَلَئِنۡ أَذَقۡنَٰهُ رَحۡمَةٗ مِّنَّا مِنۢ بَعۡدِ ضَرَّآءَ مَسَّتۡهُ لَيَقُولَنَّ هَٰذَا لِي وَمَآ أَظُنُّ ٱلسَّاعَةَ قَآئِمَةٗ وَلَئِن رُّجِعۡتُ إِلَىٰ رَبِّيٓ إِنَّ لِي عِندَهُۥ لَلۡحُسۡنَىٰۚ\nاللہ تعالیٰ نے انسان کو دو قبیح ترین صفتوں سے متصف کیا ہے۔ اگر اُسے مصیبت پہنچتی ہے تو ناامید ہوجاتا ہے، اور مایوسی کے مارے سکتے میں چلاجاتا ہے۔ اور جب اسے نعمت ملتی ہے تو وہ بھول جاتا ہے کہ اللہ ہی اس پر انعام کرنے والا اور اپنی نوازشوں سے اسے نوازنے والا ہے۔ پھر وہ اکڑنے لگتا ہے اور یہ گمان کرنے لگتا ہے کہ وہ اس نعمت کا حق دار تھا۔ اس پر مستزاد یہ کہ مرنے کے بعد دوبارہ جی اٹھنے کو جھٹلانے لگتا ہے اور کہتا ہے کہ (وما أظن الساعة قائمة)“میں نہیں سمجھتا کہ قیامت آئے گی” پھر جھٹلانے کے ساتھ مزید جھوٹا گمان یہ رکھتا ہے کہ اگر اسے مرنے کے بعد دوبارہ اٹھایا بھی گیا تو اس کے لئے اللہ کے نزدیک بہتری ہے۔ سو اس نے جہالت اور غرور کے لئے کوئی جگہ نہیں چھوڑی (یعنی جہالت اور غرور کی انتہا کو پہنچ گیا)۔ (ابن القیم: ۲؍۴۲۰)\nوہ دو قبیح ترین صفتیں کیا ہیں جن سے انسان مصیبت آتے وقت اور نعمت ملتے وقت متصف ہوتا ہے؟\nوَإِذَآ أَنۡعَمۡنَا عَلَى ٱلۡإِنسَٰنِ أَعۡرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ ٱلشَّرُّ فَذُو دُعَآءٍ عَرِيضٍ ٥١\n(فذو دعاء عريض) یعنی: بہت زیادہ، اس کے بے صبره ہونے کی وجہ سے، چنانچہ عموما انسان نہ تو پریشانیوں میں صبر کرتا ہے، اور نہ ہی آسائشوں میں شکر ادا کرتا ہے، سوائے اس کے جسے اللہ تعالىٰ ہدایت سے نواز دے، اور اس پر اپنا فضل واحسان کردے۔ (السعدی: ۷۵۲)\nمومن کو آسائشوں یا پریشانیوں میں کس حال میں رہنا واجب ہے؟\nوَإِذَآ أَنۡعَمۡنَا عَلَى ٱلۡإِنسَٰنِ أَعۡرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ ٱلشَّرُّ فَذُو دُعَآءٍ عَرِيضٍ ٥١\nاللہ تعالىٰ کے ساتھ ادب سکھلانے کی غرض سے، شر کی نسبت اللہ تعالىٰ کی طرف نہیں کی، جیسا کہ ابراہیم علیہ السلام نے کہا:﴿ٱلَّذِي خَلَقَنِي فَهُوَ يَهۡدِينِ...﴾[الشعراء: ٧٨] ،یعنى: جس نے مجھے پیدا کیا ہے وہی مجھے ہدایت دیگا، پھر کہا ﴿وَإِذَا مَرِضۡتُ فَهُوَ يَشۡفِينِ﴾ [الشعراء: ۸۰]،یعنی: اور جب میں بیمار پڑتا ہوں تو وہی مجھے شفا دیتا ہے، چنانچہ انہوں نے یہ نہیں کہا کہ: “وَإِذَا أَمْرَضَنِىْ” یعنی: جب وہ مجھے بیمار کرتا ہے’’۔ ابراہیم علیہ السلام کے اس طرح کہنے میں یہ راز اور حکمت پوشیدہ ہے کہ:نعمتیں اور بھلائیاں اپنی خلقت کے اعتبار سے انسان کے لئے مسخر ہیں، اور اس کی ذات پر غالب، اور اس کی بیشتر زندگی میں ساتھ ہوتی ہیں،کیوں کہ ان میں نوع انسانی کے بقا کا راز مضمر ہے۔ اور رہی برائیاں اور اس کے نقصانات تو عموماً یہ انسان کے غلط تصرف، اور شریعتوں نیز الہام شدہ حکماء کى طرف سے خبردار کردہ اور منع کی ہوئی چیزوں کے ارتکاب کی وجہ سے اس تک پہنچتے ہیں۔ چنانچہ عموما انسان اپنی جرأت بیجاکی وجہ سے جانتے بوجھتے ہوئے ان کا شکار ہوجاتا ہے۔(ابن عاشور: ۲۵؍۱۵)\nآیت کریمہ نے شر پہنچنے کی نسبت اللہ تعالىٰ کی طرف کیوں نہیں کى؟ نیز عموما شر انسان تک کیسے پہنچتا ہے؟\nسَنُرِيهِمۡ ءَايَٰتِنَا فِي ٱلۡأٓفَاقِ وَفِيٓ أَنفُسِهِمۡ حَتَّىٰ يَتَبَيَّنَ لَهُمۡ أَنَّهُ ٱلۡحَقُّ\nیعنی یقیناً قرآن حق ہے۔ پس اللہ تعالیٰ نے خبر دی ہے کہ وہ ضرور بالضرور انہیں (آفاق میں پھیلی ہوئی) مشاہدہ میں آنے والی آیات (یعنی نشانیاں) دکھائے گا جو ان کے لئے اس بات کو عیاں کریں گی کہ اللہ کی تلاوت کی جانے والی آیات (یعنی قرآن) حق ہیں۔ (مطلب یہ ہے کہ کائنات میں پھیلی ہوئی نشانیاں قرآن کی حقانیت کے دلائل ہیں)۔ (ابن القیم: ۲؍۴۲۰)\nکائنات اور نفس کے اندر موجود اللہ کی نشانیاں اس بات پر دلالت کرتی ہیں کہ قرآن حق ہے، آیت کی روشنی میں اسے واضح کریں؟\nسَنُرِيهِمۡ ءَايَٰتِنَا فِي ٱلۡأٓفَاقِ وَفِيٓ أَنفُسِهِمۡ حَتَّىٰ يَتَبَيَّنَ لَهُمۡ أَنَّهُ ٱلۡحَقُّ\nاس آیت میں اخبار عن الغیب -غیب کے بارے میں خبر دینے- کی شکل میں ایک معجزے کا بھی ذکر ہے، چنانچہ اس آیت نے اس وعدے کی خبر دی ہے جو اللہ تعالىٰ کی طرف سے آپ صلی اللہ علیہ وسلم اور آپ کے دین کی مدد کے تئیں کیا گیا ہے۔ اور یہ اس طرح سے حاصل ہوا کہ اللہ تعالىٰ نے آپ صلی اللہ علیہ وسلم اور آپ کے خلفاء کے لئےمشرق ومغرب میں عموما اور عرب میں خصوصا فتوحات کو آسان کیا، اور امتوں کو ان کے ذریعہ مسخر اور تابع کیا، اس طرح دیگر بادشاہوں ، رومی نیز ایرانی شہنشاہوں کے ساتھ کبھی نہیں ہوا، جبکہ مسلمان عدد کے اعتبار سے بہت تھوڑے تھے۔ (ابن عاشور: ۲۵؍۱۸)\nاس آیت میں ایک غیبی معجزہ ہے، اس کی وضاحت کرو؟\nأَلَآ إِنَّهُمۡ فِي مِرۡيَةٖ مِّن لِّقَآءِ رَبِّهِمۡۗ\nعمر بن عبد العزیز -رحمہ اللہ- ایک دن منبر پر چڑھے، اللہ تعالىٰ کی حمد وثناء بیان کی، پھر کہا: \" اما بعد: اے لوگو! میں نے تمہیں کسی نئی چیز کے لئے نہیں جمع کیا ہے، البتہ میں نے اس چیز کے بارے میں سوچا جس کى طرف تم جانے والے ہو، چنانچہ میں نے یہ جانا کہ اس -قیامت کے دن- کی تصدیق کرنے والا احمق، اور اس کی تکذیب کرنے والا ہلاک وبرباد ہونے والا ہے\"۔ یہ کہہ کر آپ منبر سے اتر گئے۔ یہاں آپ نے اس -قیامت-کی تصدیق کرنے والے کو احمق اس لئے کہا، کیونکہ وہ اس کے مطابق عمل نہیں کرتا، اس سے ڈرتا نہیں ہے، اس کی ہولناکی سے خوف نہیں کھاتا ہے، حالانکہ وہ اس کی تصدیق کرتا ہے، اس کے واقع ہونے پر یقین رکھتا ہے، پھر بھی وہ اپنے لہو ولعب اور غفلت وسرکشى میں ڈوبا رہتا ہے۔ چنانچہ وہ اس اعتبار سے احمق ہے۔ اور احمق عربی زبان میں کم عقل کو کہتے ہیں۔ (ابن کثیر: ۴؍۱۰۷)\nجو لوگ قیامت کے دن کو مانتے ہیں ان کی حالت دیکھ کر لگتا ہے کہ وہ بھی اس کے تئیں شک وشبہ میں مبتلا ہیں، اس کی وضاحت کیجئے؟\nwords\nأَكمَامِهَااپنے غلافوں (گھابوں )سے.\nآذَنَّاكَهم آپ كو آگاه كرتے هيں.\nمَحِيصٍجائے پناه ؛ جائے فرار.\nلاَ يَسأَمُوه ملول نهيں هوتا.\nوَنَأَى بِجَانِبِهِشكرنعمت سے دور هوا / اتباع حق سے محروم هوا.\nفَذُو دُعَاءٍ عَرِيضٍتكليف ختم هونے كے ليے بهت زياده دعا كرنے والا.\nشِقَاقٍايسے اختلاف ميں هو جو حق سے بهت دور هے."],[483,"§الشورى\ndeeds\nفرشتوں کی اقتداء کرتے ہوئے اپنے، اور روئے زمین پر بسنے والے تمام مومن مردوں اور مومن عورتوں کے لئے استغفار کیجئے.\nمسجد میں موجود لوگوں کو نصیحت کیجئے، یا قیامت کے بارے میں ایک پیغام بھیجئے.\nکسی ایسے مسئلہ کو دیکھئے جس کے بارے میں آپ کے ارد گرد موجود لوگ اختلاف کا شکار ہوں،اس مسئلہ میں اللہ کا حکم تلاش کیجئے، اور لوگوں کو دلیل کی روشنی میں نصیحت کیجئے.\nguid\nمومن اپنے مومن بھائیوں کا غمگسار ہوتا ہے، اور ان کا غم اٹھاتا ہے.\nدروس و مواعظ کے لئے سب سے بہترین کتاب قرآن کریم ہے.\nصحیح دین سیکھنے کے لئے ہمیشہ عربی زبان ہی کنجی اوراصل ذریعہ رہے گی، لہذا اسے سیکھنے کی دل سے کوشش کیجئے.\nrefl\nكَذَٰلِكَ يُوحِيٓ إِلَيۡكَ وَإِلَى ٱلَّذِينَ مِن قَبۡلِكَ ٱللَّهُ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ٣\nیہاں پر اللہ تعالىٰ نے (العزيز) اور (الحكيم) کی صفت کو خصوصیت کے ساتھ ذکر کیا ہے کیوں کہ اللہ تعالىٰ کے فرمان: “اللہ تعالىٰ جسے چاہتا ہے رسالت کے لئے اختیار کرتا ہے” کا جو مقصد ہے اس سے ان دونوں صفتوں کا گہرا اور خصوصی تعلق ہے۔ (ابن عاشور: ۲۵؍۲۷)\nآیت کریمہ کو (العزيز)اور(الحكيم) کی صفت کےساتھ کیوں ختم کیا گیا ہے؟\nتَكَادُ ٱلسَّمَٰوَٰتُ يَتَفَطَّرۡنَ مِن فَوۡقِهِنَّۚ\nاس کا مطلب یہ ہے کہ مشرکین کا یہ کہنا: (اتخذ الله ولدا) [البقرة: ۱۱۶]کہ اللہ تعالىٰ نے اپنےلئے لڑکا اختیار کرلیا ہے، اس قدر سنگین ہے کہ اس کی سنگینی کیوجہ سےقریب ہے کہ ہر آسمان اپنے نیچے والے آسمان پر پھٹ کرگرپڑے۔ (القرطبی: ۱۸؍۴۴۴)\nکس وجہ سے قریب ہے کہ آسمان پھٹ پڑے؟\nتَكَادُ ٱلسَّمَٰوَٰتُ يَتَفَطَّرۡنَ مِن فَوۡقِهِنَّۚ وَٱلۡمَلَٰٓئِكَةُ يُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡ\nتسبیح کو حمد پر مقدم کرنے میں یہ اشارہ ہے کہ اللہ تعالىٰ کی ذات کو اس کے لئے نامناسب چیزوں سے پاک کرنا، اس کے لئے صفات کمال کو ثابت کرنے سے زیادہ اہم ہے،اس لئے کہ پاکی بیان کرنا یہ در اصل اس کے کمالات کو پالینے کی تمہید ہے۔ (ابن عاشور: ۲۵؍۳۳)\nتسبیح کو حمد پر مقدم کرنے میں کیا فائدہ ہے؟\nوَٱلۡمَلَٰٓئِكَةُ يُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡ وَيَسۡتَغۡفِرُونَ لِمَن فِي ٱلۡأَرۡضِۗ\nفرشتے اپنے رب سے زمین پر بسنے والے مومنین کے گناہوں کے لئے مغفرت طلب کرتے ہیں۔ (الطبری: ۲۱؍۵۰۲)\nجومخلوق اللہ تعالىٰ سے سب سے زیادہ قریب ہوگی، وہی اللہ کی مخلوقات پر سب سے زیادہ رحم کھانے والی ہوگی۔ آیت کی روشنی میں اس کی وضاحت کیجئے؟\nوَمَا ٱخۡتَلَفۡتُمۡ فِيهِ مِن شَيۡءٖ فَحُكۡمُهُۥٓ إِلَى ٱللَّهِۚ\nاس آیت سے یہ پتہ چلتا ہے کہ امت کا اتفاق قطعی حجت ہے، اس لئے کہ اللہ تعالىٰ نے ہمیں انہیں معاملات کو اپنى طرف لوٹانے کے لئے کہا ہے جن میں ہمارا اختلاف ہوجائے، چنانچہ جن امور میں ہم متفق ہوں گے ان میں امت کا اتفاق کافی ہوگا، اس لئے کہ امت معصوم عن الخطا ہے، اور وہ گمراہی پر متفق نہیں ہوسکتی، ہاں البتہ یہ ضروری ہے کہ اس امت کا اتفاق کتاب اللہ اور سنت رسول صلی اللہ علیہ وسلم کے مطابق ہو۔ (السعدی: ۷۵۳)\nیہ آیت اجماع کی حجیت-اجماع کے دلیل ہونے- پر کیسے دلالت کرتی ہے؟\nعَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ أُنِيبُ ١٠\nاللہ تعالىٰ ان دونوں -توکل اور عبادت- اصل کا اپنى کتاب میں کثرت سے ذکر کرتا ہے، کیونکہ بیک وقت ان دونوں کے ذریعہ بندہ کمال تک پہنچتا ہے، اور ان دونوں یا ان میں سے کسی ایک کے فوت ہونے سے کمال کا مرتبہ اس سے فوت ہوجاتا ہے، جیسا کہ ارشاد باری تعالىٰ ہے: ﴿إِيَّاكَ نَعۡبُدُ وَإِيَّاكَ نَسۡتَعِينُ﴾[الفاتحہ: ۵]، یعنی: ہم تیری ہی عبادت کرتے ہیں اور تجھی سے مدد مانگتے ہیں، نیز ارشاد ربانی ہے: ﴿فَٱعۡبُدۡهُ وَتَوَكَّلۡ عَلَيۡهِ﴾ [هود: ۱۲۳]،پس اسی کی عبادت کر، اور اسی پر بھروسہ رکھ’’۔ (السعدی: ۷۵۴)\nکیا وجہ ہے کہ قرآن میں توکل اور عبادت کو بکثرت ایک ساتھ ذکر کیا گیا ہے؟\nذَٰلِكُمُ ٱللَّهُ رَبِّي عَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ أُنِيبُ ١٠\nیہاں (تَوَكَّلْتُ) فعل ماضی اور (أنيب) فعل مضارع لایا گیا ہے، اس میں اس بات کی طرف اشارہ ہے کہ آپ صلی اللہ علیہ وسلم کا اللہ تعالىٰ پر بھروسہ آپ کی قوم کی طرف سے بے رخی اور بے اعتنائی کے ظہور سے پہلے سے ہے، اور یہ اتفاق ہے کہ اس قوم نے ایک ایسے بندے کیساتھ بے اعتنائی برتی جو اپنے رب پر بھروسہ کرنے والا ہے۔ رہا (أنيب) کا فعل تو اس کےمضارع لانے میں اس بات کی طرف اشارہ ہے کہ یہ انابت کی صفت آپ کے اندر تجدد پذیر ہے، یعنی:یہ صفت آپ کے اندر مختلف اوقات میں حسب حاجت وضروت تسلسل کے ساتھ پیدا ہوتے رہتی ہے۔(ابن عاشور: ۲۵؍۴۳)\n(تَوَكَّلْتُ) کے فعل کو ماضی اور (أنيب) کے فعل کو مضارع کے صیغے میں کیوں لایا گیا ہے؟\nwords\nيَتَفَطَّرنَوه پھٹ جائيں.\nأَولِيَاءَوه معبود جنهيں اپنا كارساز سمجھتے هيں ؛ ان كي عبادت كرتے هيں.\nحَفِيظٌبهت سخت محافظ.\nأُمَّ القُرَىمكه / مراد اهل مكه هيں.\nلاَ رَيبَ فِيهِلاَ شَكَّ فِي مَجِيئِهِ.\nأُمَّةً وَاحِدَةًهدايت پر جمع هونے والے.\nوَإِلَيهِ أُنِيبُتمام امور ميں اسي كي طرف رجوع كرتا هوں."],[484,"§الشورى\ndeeds\nاپنے کسی دوست یا قریبی رشتہ دار کو کسی عبادت یا ایسی سنت کی طرف جس پر آپ عمل پیرا ہوں بلائیں.\nاللہ تعالىٰ کے اوامر کی پابندی کرتے ہوئے آپ یہ جملہ کہیں.\nکوئی ایسی بدعت یا معصیت جو آپ کے ارگرد پھیل چکی ہو اس پر نظر رکھئے، اور اس سے خود دورى بنالیجئے، نیز دوسروں کو بھی اس سے ڈرایئے.\nguid\nاللہ تعالىٰ کے لئے صفات کو ثابت کیجئے، اور مخلوقات سے اس کی مشابہت کی نفی کیجئے.\nاللہ تعالىٰ نے آپ کے لئے جوروزی مقرر کر رکھی ہے اس پر راضی رہئے، کیونکہ روزی کو کشادہ اور تنگ کرنے والی ذات اللہ تعالىٰ کی ہے.\nاگر بندے کا مقصد نیک ہو، اور ساتھ ہی ساتھ وہ ہدایت کی تلاش وطلب میں کوشاں ہو، تو یہ چیز اس کےہدایت پانے میں آسانی پیدا کرتى ہے.\nrefl\n۞شَرَعَ لَكُم مِّنَ ٱلدِّينِ مَا وَصَّىٰ بِهِۦ نُوحٗا وَٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ وَمَا وَصَّيۡنَا بِهِۦٓ إِبۡرَٰهِيمَ وَمُوسَىٰ وَعِيسَىٰٓۖ\nیہ سب سے بڑی نعمت ہے جو اللہ تعالىٰ نے اپنے -مسلمان- بندوں پر کی ہے، کہ اس نے مختلف ادیان میں جو دین سب سے بہتر، سب سے افضل، سب سے پاک، اور سب سے صاف ہے اسے ان کے لئے مقرر اور اختیار کیا، اور وہ دین اسلام ہے جسے اللہ تعالىٰ نے اپنے پسندیدہ اور چنیدہ بندوں کے لئے اختیار کیا ہے، بلکہ حقیقت یہ ہے کہ اسے اللہ تعالىٰ نے اپنے پسندیدہ اور چنیدہ ترین بندوں کے لئے مقرر کیاہے، اور وہ اولوا العزم اور وہ برگزیدہ رسول ہیں جن کا ذکر اس آیت میں آیا ہے، وہ مخلوقات میں سب سے بلند مرتبہ کے حامل، اور ہر اعتبار سے سب سے کامل ہیں۔ (السعدی : ۷۵۴)\nاللہ تعالىٰ نے آپ پر سب سے عظیم نعمت کون سی کی ہے؟\n۞شَرَعَ لَكُم مِّنَ ٱلدِّينِ مَا وَصَّىٰ بِهِۦ نُوحٗا وَٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ وَمَا وَصَّيۡنَا بِهِۦٓ إِبۡرَٰهِيمَ وَمُوسَىٰ وَعِيسَىٰٓۖ أَنۡ أَقِيمُواْ ٱلدِّينَ وَلَا تَتَفَرَّقُواْ فِيهِۚ\nہمارے نبی محمد صلی اللہ علیہ وسلم کا لایا ہوا دین عقیدہ کے اصول میں تمام انبیاء سے متفق اور ان کے لائے ہوئے دین کے موافق ہے، اور یہی چیز یہاں مراد ہے، اسی لئے یہاں اس کی تفسیر اللہ تعالىٰ کے قول: (أن أقيموا الدين) سے کی گئی ہے، یعنی: اسلام کو قائم کرنا، جو درحقیقت اللہ تعالىٰ کو ایک جاننے، اس کی اطاعت کرنے، اور اس کے رسولوں، اسکی کتابوں، اور آخرت پر ایمان لانے کا نام ہے۔ اور جہاں تک فروعی احکام کا مسئلہ ہے تو ان میں شریعتوں کے درمیان اختلاف ہے، چنانچہ وہ یہاں مراد نہیں ہیں۔ (ابن جزی: ۲؍۲۹۹)\nوہ کون سے امور ہیں جن میں انبیاء کے پیغامات متفق ہیں؟ اور وہ کون سے امور ہیں جن میں مختلف ہیں؟\nأَنۡ أَقِيمُواْ ٱلدِّينَ وَلَا تَتَفَرَّقُواْ فِيهِۚ\nاللہ تعالىٰ نے تمام انبیاء کو اقامت دین، الفت ومحبت اور اتحاد واتفاق پیدا کرنے، نیز اختلاف وفرقہ پرستی کو ترک کرنے کی خاطر بھیجا۔ (البغوی: ۴؍۷۷)\nاس آیت سے ایسی کس جامع علامت کا پتہ چلتا ہے جس کی خاطر اللہ تعالىٰ نے تمام انبیاء کو بھیجا؟\nكَبُرَ عَلَى ٱلۡمُشۡرِكِينَ مَا تَدۡعُوهُمۡ إِلَيۡهِۚ\nیعنی: آپ جو انھیں اللہ تعالىٰ کی وحدانیت اور بت پرستی کو ترک کرنے کی طرف دعوت دے رہے ہیں، یہ چیز ان پر بہت گراں گزر رہی ہے۔ قتادہ نے کہا: مشرکوں پر یہ بات بہت بھاری پڑى اور نہایت گراں گزری کہ وہ اللہ کے وحدانیت کی گواہی دیں، اور ابلیس اور اسکے لشکر کو اس سے تنگی محسوس ہوئى، مگر اللہ تعالىٰ نےیہ فیصلہ کرلیا کہ وہ اس کی مدد کریگا، اسے اعلى شان عطا کریگا، اور جو اس سے دشمنى کریگا اس پر اسے غالب کرکے چھوڑے گا۔ (القرطبی: ۱۸؍۴۵۳)\nوہ کونسی چیز ہے جو مشرکوں کو بہت بھاری پڑتی، اور ان پر نہایت گراں گزرتی ہے؟\nوَمَا تَفَرَّقُوٓاْ إِلَّا مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡعِلۡمُ بَغۡيَۢا بَيۡنَهُمۡۚ\nسیادت وقیادت کی خواہش میں ایک دوسرے پر ظلم کرنے کی وجہ سے وہ علم آنے کے بعد اختلاف کا شکار ہوگئے، چنانچہ ان کا اختلاف اور ان کی تفرقہ بازی دلیلوں اور وضاحتوں میں قصور کا نتیجہ نہیں تھی، بلکہ ظلم وزیادتی اور دنیا پرستی اس کا سبب تھی۔ (القرطبی: ۱۸؍۴۵۴)\nعلم ہونے کے باوجود بعض نامور مسلمانوں کے اختلاف اور تفرقہ کی کیا وجہ ہے؟\nوَمَا تَفَرَّقُوٓاْ إِلَّا مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡعِلۡمُ\nجب اللہ تعالىٰ نے مسلمانوں کو یہ حکم دیا کہ وہ اپنے دین پر اتحاد واتفاق کے ساتھ جمے رہیں، اور اختلاف وتفرقہ کا شکار نہ ہوں، تو ساتھ ہی ساتھ یہ بھی بتلا دیا کہ وہ اس بات سے دھوکہ نہ کھائیں کہ ان پر اللہ تعالىٰ نے کتاب نازل کی ہے، کیوں کہ اہل کتاب تو اسی وقت تفرقہ کے شکار ہوئے جب اللہ تعالىٰ نے ان پر وہ کتاب نازل کی جس کا تقاضہ یہ تھا کہ وہ اتحاد واتفاق سے رہیں۔ (السعدی: ۷۵۵)\nیہاں اللہ تعالىٰ نے ہم سے پہلے اہل کتاب کے بارے میں جو خبر دی ہے اس سے مسلمانوں کو کیا سیکھ ملتی ہے؟\nوَلَا تَتَّبِعۡ أَهۡوَآءَهُمۡۖ\nیہاں اللہ تعالىٰ نے یہ نہیں کہا کہ (ولا تتبع دينهم) یعنی: ان کے دین کی اتباع نہ کرو، بلکہ یہ کہا کہ: (وَ لَا تتبع أهواءهم) یعنی: ان کے خواہشات کی پیروی نہ کرو، اس لئے کہ جس دین کو اللہ تعالىٰ نے ان کے لئے مقرر کیا ہے درحقیقت وہ سارے رسولوں کا دین ہے، لیکن ان لوگوں نے اس کی اتباع نہیں کی، بلکہ اس کے بجائے اپنی خواہشات کی پیروی کی، اور اپنے حقیقی دین کو لہو ولعب بنا لیا۔ (السعدی: ۷۵۵)\nاس آیت میں بدعت کی سنگینی کی طرف توجہ دلائی گئى ہے، اس کی وضاحت کیجئے؟\nwords\nفَاطِرُخالق / موجد.\nيَذرَؤُكُم فِيهِوه تمهيں زياده كرتاهے؛ شاديوں كے سبب.\nمَقَالِيدُ السَّمَاوَاتِآسمانوں كي بادشاهي؛ خزانوں كي چابياں.\nيَبسُطُوه وسعت ديتا هے.\nوَيَقدِرُوه تنگي كرتا هے.\nيَجتَبِي إِلَيهِوه چن ليتا هے اپني توحيد او راپنے دين كے ليے.\nيُنِيبُوه اطاعت كرتے هوئے اس كي طرف رجوع كرتا هے.\nمُرِيبٍشك كے مواقع ؛ اور مذموم اختلاف."],[485,"§الشورى\ndeeds\nکوئی ایسا عمل کیجئے جو اس بات پر دلالت کرے کہ قربِ قیامت پر آپ کا ایمان ہے.\nاپنے بارے میں غور کریں، اور اپنے آپ پر اللہ تعالىٰ کی تین مہربانیوں کو نوٹ کریں.\nاپنے دل میں کسی عظیم عمل کو انجام دینے کی خواہش پیدا کیجئے، اور پھر اسے پورا کرنے میں لگ جایئے، یہاں تک کہ اللہ تعالىٰ آپ کو دیگر نیک اعمال کرنے کی بھی توفیق دے.\nguid\nقرآن کریم اور میزان نازل کرنے میں پوشیدہ بعض حکمتوں کابیان، اور وہ یہ ہے کہ لوگوں کے درمیان عدل وانصاف قائم ہو.\nواجبی طور پر نیتوں کی اصلاح کا بیان، کیونکہ عمل کے قبول اور رد ہونے کا دار و مدار اسی پر ہے.\nبدعتوں سے بچئے، کیونکہ گزشتہ ادیان میں انحراف و بگاڑ کا ایک سبب بدعتیں بھی تھیں، مزید یہ اللہ تعالىٰ کے غضب کا سبب بنتی ہیں، چنانچہ آپ دیکھیں گے کہ شیطان بدعتی بندے کو بدعات سے دور نہیں ہونے دیتا.\nrefl\nٱللَّهُ ٱلَّذِيٓ أَنزَلَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ وَٱلۡمِيزَانَۗ وَمَا يُدۡرِيكَ لَعَلَّ ٱلسَّاعَةَ قَرِيبٞ ١٧\nاگر یہ کہا جائے کہ کتاب اللہ اور میزان کے بعد قیامت کا ذکر کیوں آیا ہے؟ تو اس کا جواب یہ ہوگا کہ قیامت بدلہ اور حساب کا دن ہے، پس گویا یہ کہا جارہا ہے انصاف سے کام لو اور نیک اور سچے کام کرو، ا س دن سے پہلے جس میں تمہارا محاسبہ کیا جائیگا۔ (ابن جزی: ۲؍۳۰۰)\nکتاب اور میزان کے بعد قیامت کا ذکر کیوں آیا ہے؟\nيَسۡتَعۡجِلُ بِهَا ٱلَّذِينَ لَا يُؤۡمِنُونَ بِهَاۖ وَٱلَّذِينَ ءَامَنُواْ مُشۡفِقُونَ مِنۡهَا\nیعنی: مومنین قیامت کے دن پر ایمان رکھنے کیوجہ سے اس سے خائف ہیں، کیونکہ وہ جانتے ہیں کہ اس دن اعمال کا بدلہ ملے گا، اور ان کے خوف کا سبب یہ ہے کہ وہ اپنے رب کو جانتے ہیں، اور انھیں یہ ڈر ستا رہا ہے کہ کہیں ایسا نہ ہو کہ ان کے اعمال ان کی نجات اور سعادت کے لئے کافی نہ ہوں۔ (السعدی: ۷۵۶)\nقیامت کے دن سے مومنین کے خوف کی وجہ کیا ہے؟\nٱللَّهُ لَطِيفُۢ بِعِبَادِهِۦ يَرۡزُقُ مَن يَشَآءُۖ\nبندوں پر اللہ تعالىٰ کی مہربانیوں کا ایک نمونہ یہ ہے کہ اللہ تعالىٰ نے بندے کے لئے ایسے اسباب مہیا کردیئے ہیں جو اسے برائی سے روکیں، اور اس کے اور معصیت کے درمیان دیوار بن کر حائل ہو جائیں، چنانچہ جب اللہ تعالىٰ نے یہ جان لیا کہ دنیا، مال اور سیادت وقیادت جیسے امور جن میں اہل دنیا مقابلہ کرتے ہیں، یہ چیزیں بندے کو اس کی اطاعت وفرمانبرداری سے الگ کردیتی ہیں، یا اس کو اللہ تعالىٰ سے غفلت یا اس کی نا فرمانی پر ابھارتی ہیں، تو اللہ تعالىٰ نے بندے سے ان چیزوں کو دور کردیا، اور اس کے رزق کو اس کے لئے مقدر ومہیا کردیا، اسی لئے فرمایا:(يرزق من يشاء)یعنی: جسے چاہتا ہے رزق دیتا ہے۔\nاللہ تعالىٰ نے اپنے بندوں پر مہربانی کے بعد رزق کا ذکر کیوں کیا؟\nٱللَّهُ لَطِيفُۢ بِعِبَادِهِۦ يَرۡزُقُ مَن يَشَآءُۖ وَهُوَ ٱلۡقَوِيُّ ٱلۡعَزِيزُ ١٩\n(وهو القوي العزيز)کو (لطيف) پر، یا (يرزق من يشاء) کے جملہ پر عطف کیا گیا ہے، یہاں درحقیقت ان دونوں صفتوں کے ذریعہ اللہ تعالىٰ کی بزرگی وبڑائی مقصود ہے۔ اسی طرح ان دونوں صفتوں کا یہاں ذکر اس وہم سے بچاتا ہے کہ اللہ تعالىٰ کی بندوں پر یہ مہربانیاں عاجزی یا تکلف وتصنع کا نتیجہ ہیں، کیونکہ اللہ تعالىٰ قوی اور غالب ہے، نہ تو عاجز ہوتا ہے، نہ اسے تکلف اور تصنع کی ضرورت ہے۔ اسی طرح اس وہم کو دور کرتی ہیں کہ اللہ تعالىٰ بخل یا قلت کی وجہ سے -سب کے بجائے- صرف انہیں لوگوں کو دیتا ہے جنھیں چاہتا ہے، اس لئے کہ وہ قوی اور طاقت ور ہے، اور قوی و طاقت ور ذات سے بخل کے اسباب دور ہوتے ہیں، اسی طرح غالب ذات سے فقر کے اسباب دور ہوتے ہیں، چنانچہ اللہ تعالىٰ کا- جسے چاہے اور جتنا چاہے- روزی دینا اس کے اس حکمت کی بنا پر ہے جسے وہ اپنی مخلوقات کے عمومی اور خصوصی حالات کے تئیں جانتا ہے۔ (ابن عاشور: ۲۵؍۷۳)\n(وهو القوي العزيز)کو (لطيف) پر عطف کرنے کا کیا فائدہ ہے؟\nٱللَّهُ لَطِيفُۢ بِعِبَادِهِۦ يَرۡزُقُ مَن يَشَآءُۖ وَهُوَ ٱلۡقَوِيُّ ٱلۡعَزِيزُ ١٩\nمحمد بن علی الکتانی نے فرمایا: لطیف وہ ذات ہے جس کے پاس اس کے بندے اس وقت پناہ لیں جب وہ مخلوقات سے مایوس ہو جائیں، اور جس پر بندے بھروسہ کریں، اور اس کی طرف رجوع کریں، تو اس وقت وہ ذات ان کو قبول کرتی ہے، اور ان کی طرف متوجہ ہوتی ہے۔ اور یہ بھی کہا گیاہے کہ: لطیف وہ ہے جو بندوں کی اچھائیوں کو پھیلاتا اور ان کے عیوب کی پردہ پوشی کرتا ہے۔ اور یہ بھی کہا گیا ہے کہ: لطیف وہ ہے جو تھوڑی سى چیز کو قبول کرتا ہے، اور بدلہ میں بڑی چیزیں عطا کرتا ہے۔ اسی طرح یہ بھی کہا گیا کہ: لطیف وہ ہے جو ٹوٹے ہوئے شخص کی دل جوئی کرتا ہے، اور تنگ دست کے لئے آسانی فراہم کرتا ہے۔ نیز کہا گیا کہ: لطیف وہ ہے جو اپنی نافرمانی کرنے والے کو سزا دینے میں جلدی نہیں کرتا، اور اس سے امید رکھنے والے کو مایوس نہیں کرتا۔ اسی طرح کہا گیا کہ: لطیف وہ ہے جو اپنے سائل کو نامراد نہیں لوٹاتا، اور اس سے امید رکھنے والے کی آرزو پوری کرتا ہے۔ اسی طرح کہا گیا کہ: لطیف وہ ہے جو غلطی کرنے والے سے در گزر کرتا ہے۔ اسی طرح کہا گیا کہ: لطیف وہ ہے جو اس شخص پر بھی رحم کرتا ہےجو خود پر رحم نہیں کرتا۔ (القرطبی: ۱۸؍۴۵۹-۴۶۱)\nاللہ تعالىٰ کی اپنے بندوں پر مہربانیوں کے بارے میں آپ کیا جانتے ہیں؟\nمَن كَانَ يُرِيدُ حَرۡثَ ٱلۡأٓخِرَةِ نَزِدۡ لَهُۥ فِي حَرۡثِهِۦۖ\nاس کا مطلب یہ ہے کہ جو شخص ہمارى عطا کردہ چیزوں کے ذریعہ آخرت کا طلبگار ہوتا ہے، چنانچہ وہ اللہ تعالىٰ کے حقوق کو ادا کرتا ہے، اور دین کو مضبوط کرنے کے لئے خرچ کرتا ہے، تو ہم اسے ایک کا اجر وثواب دس (۱۰) سے سات سو (۷۰۰) گنا تک دیتے ہیں۔ (القرطبی: ۱۸؍۴۶۱)\nکھیتی میں زیادتی کا کیا مطلب ہے؟\nوَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ فِي رَوۡضَاتِ ٱلۡجَنَّاتِۖ لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمۡۚ ذَٰلِكَ هُوَ ٱلۡفَضۡلُ ٱلۡكَبِيرُ ٢٢\nیہاں ایک باریکی یہ بھی ہے کہ آیت کریمہ میں باتیں اسی ترتیب سے آئی ہیں جس ترتیب سے وہ عملا ہمارے یہاں واقع ہوتی ہیں، چنانچہ جب کوئی مہمان یا زائر آتا ہے تو اسےسب سے پہلے عزت واکرام کی جگہ بیٹھایا جاتا ہے، پھر اس کی ضیافت کی جاتی ہے اور اس کو کھانا وغیرہ پیش کیا جاتا ہے، پھر گھر کا مالک اس سے قربت بڑھاتا اور اس کے ساتھ گھلنے ملنے لگتا ہے۔ (ابن عاشور ۲۵؍۷۹)\nاس آیت کریمہ کے اندر جنت میں مومنین کے لئے اکرام وتکریم کےتین مراتب ذکر کئے گئے ہیں، ان کی وضاحت کیجئے؟\nwords\nيُحَآجُّونَ فِي اللهِالله كے دين ميں جھگڑا كرتے هيں.\nدَاحِضَةٌختم هونے والي؛ باطل.\nمُشفِقُونَ مِنهَاوه اس كے قيام سے ڈرتے هيں.\nيُمَارُونَوه جھگڑا كرتے هيں.\nحَرثَ الآخِرَةِآخرت كا ثواب.\nكَلِمَةُ الفَصلِان كو مهلت دينے كا فيصله."],[486,"§الشورى\ndeeds\nآپ یہ دعا کریں: اللہ تعالىٰ میری توبہ قبول کر، اور میرے گناہوں کو بخش دے.\nان آیات میں اللہ تعالىٰ نے جن چیزوں کا حکم دیا ہے ان میں سے کوئی ایک حکم ابھی بجا لائیں تاکہ اللہ آپ پر مزید فضل واحسان کرے.\nکوئی ایسی مصیبت یاد کیجئے جو آپ پر آئی ہو، پھر اللہ تعالىٰ سے بکثرت استغفار کیجئے، اوریہ آیت ذہن نشین رکھئے.\nguid\nاللہ تعالىٰ نے باطل کو مٹانے کا وعدہ کر رکھا ہے.\nمخلوقات کے درمیان رزق کی تقسیم میں اللہ تعالىٰ کی حکمت پوشیدہ ہے.\nبندوں پر اللہ تعالىٰ کی رحمت کے مختلف مظاہر میں سے ایک مظہر بارش کا نزول ہے، جو شکر کا مستحق ہے.\nrefl\nذَٰلِكَ ٱلَّذِي يُبَشِّرُ ٱللَّهُ عِبَادَهُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِۗ\nجب اللہ تعالىٰ نے اپنے مومن اور نیک وصالح بندوں کے لئے جنت کی کیاریوں کا تذکرہ کیا تو فرمایا: (ذلك الذي يبشر الله عباده الذين آمنوا وعملوا الصالحات)، یعنی: یہ چیز ان کو ہر حال میں ملے گی، کیونکہ اللہ تعالىٰ نے ان کو اس کی خوش خبری دے رکھی ہے۔ (ابن کثیر: ۴؍۱۱۴)\nاس آیت میں مومنوں کے لئے بشارت کی وجہ کیا ہے؟\nوَهُوَ ٱلَّذِي يَقۡبَلُ ٱلتَّوۡبَةَ عَنۡ عِبَادِهِۦ وَيَعۡفُواْ عَنِ ٱلسَّيِّـَٔاتِ وَيَعۡلَمُ مَا تَفۡعَلُونَ ٢٥\nچونکہ توبہ ان عظیم اعمال میں سے ہے جو کبھی پورے اخلاص وسچائی کیوجہ سے مکمل ہوتے ہیں، اور کبھی اخلاص وصدق میں نقص وکمی کی وجہ سے ناقص ہوتے ہیں، اور بسا اوقات اس وجہ سے فاسد ہوجاتے ہیں کہ ان کا مقصد اخلاص وصدق کے بجائے کوئی دنیاوی مقصد حاصل کرنا ہوتا ہے، اور اس کا اصل مقام ومرجع وہ دل ہے جسکی حقیقت اللہ تعالىٰ کے سوا کوئی نہیں جانتا، اسی لئے اللہ تعالىٰ نے اس آیت کو اپنے فرمان: (ويعلم ما تفعلون) سے ختم کیا۔ (السعدی: ۷۵۸)\nاللہ تعالىٰ نے اس آیت کو اپنے فرمان: (ويعلم ما تفعلون) سےکیوں ختم کیا ہے؟\nوَهُوَ ٱلَّذِي يَقۡبَلُ ٱلتَّوۡبَةَ عَنۡ عِبَادِهِۦ وَيَعۡفُواْ عَنِ ٱلسَّيِّـَٔاتِ وَيَعۡلَمُ مَا تَفۡعَلُونَ ٢٥\nیہاں پر اللہ تعالىٰ نے (الناس) یا (التائبين) یا ان کی طرح کوئی لفظ ذکر کرنے کے بجائے (عِبَادِ) یعنی: بندوں کا لفظ ذکر کیا ہے، جس میں اس بات کی طرف اشارہ ہے کہ اللہ تعالىٰ اپنے بندوں پر مہربان اور ان کے ساتھ مقام عبودیت کیوجہ سے نرم و شفیق ہے، کیونکہ ہر بنانے اور ایجاد کرنے والا اپنی بنائی ہوئی چیز کی اصلاح چاہتا ہے۔ (ابن عاشور: ۲۵؍۹۰)\nاس آیت کریمہ میں (الناس) یا (التائبين) کے بجائے (عِبَادِ) کی تعبیر کیوں استعمال کی گئی ہے؟\n۞وَلَوۡ بَسَطَ ٱللَّهُ ٱلرِّزۡقَ لِعِبَادِهِۦ لَبَغَوۡاْ فِي ٱلۡأَرۡضِ وَلَٰكِن يُنَزِّلُ بِقَدَرٖ مَّا يَشَآءُۚ إِنَّهُۥ بِعِبَادِهِۦ خَبِيرُۢ بَصِيرٞ ٢٧\nاللہ تعالىٰ بعض بندوں کے حالات کے بارے میں یہ جانتا ہے کہ اگر ان کے رزق میں کشادگی کی تو یہ چیز ان کو بگاڑ دیگی، چنانچہ ان ہی کی مصلحت کی رعایت کرتے ہوئے ان پر دنیا کو کشادہ نہیں کرتا، اور رزق کو ان پر ذرا تنگ کردیتا ہے، اس لئے کبھی بھی یہ نہیں سوچنا چاہیئے کہ محض رزق کی تنگی ذلت وہوان، اور مجرد اس کی کشادگی کوئی فضیلت کی چیز ہے۔ بعض روایتوں میں آتا ہے کہ اللہ تعالىٰ فرماتا ہے:“میر ے کچھ مومن بندے ایسے ہیں جو مجھ سے بعض اہم عبادتوں کی توفیق مانگتے ہیں، اور میں جانتا ہوں کہ اگر میں انہیں یہ عطا کردوں تو یہ چیز انہیں تکبر کا شکار کرکے بگاڑ دیگی، اسی طرح میرے بعض بندے ایسے ہیں جن کے لئے مالدارى ہی بہتر ہے، اور اگر انہیں میں فقیر بنادوں تو یہ فقر انہیں بگاڑ دے گا، اسی طرح میرے بعض بندے ایسے ہیں جن کے لئے فقیری ہی بہتر ہے، اور اگر انہیں میں مالداری عطا کردوں تو یہ مالداری انہیں بگاڑ دے گی”۔ (القرطبی: ۱۸؍۴۷۵ )\nکیا رزق میں کشادگی ہر حال میں انسان کے لئے بہتر ہے؟\nوَهُوَ ٱلَّذِي يُنَزِّلُ ٱلۡغَيۡثَ مِنۢ بَعۡدِ مَا قَنَطُواْ وَيَنشُرُ رَحۡمَتَهُۥۚ وَهُوَ ٱلۡوَلِيُّ ٱلۡحَمِيدُ ٢٨\nیہاں دیگر دنیوی نعمتوں کو چھوڑ کرخصوصیت کے ساتھ بارش کی نعمت کو اس لئے ذکر کیا ہے کیونکہ اس کے عظیم نعمت ہونے میں لوگوں کا کوئی اختلاف نہیں ہے، اس کی وجہ یہ ہے کہ اس پر زندگی کا دارو مدار ہے، چنانچہ لوگوں اور چوپایوں کے لئے غذا اور چارہ اسى سے پیدا ہوتا ہے۔ (ابن عاشور: ۲۵؍۹۵)\nاللہ تعالىٰ نے یہاں رزق کے عمومی ذکر کے بعد خصوصیت کے ساتھ بارش کا ذکر کیوں کیا ہے؟\nوَهُوَ ٱلَّذِي يُنَزِّلُ ٱلۡغَيۡثَ مِنۢ بَعۡدِ مَا قَنَطُواْ وَيَنشُرُ رَحۡمَتَهُۥۚ وَهُوَ ٱلۡوَلِيُّ ٱلۡحَمِيدُ ٢٨\nیہاں دیگر صفات کے بجائے (الولي) اور (الحميد) کی صفات کو خصوصیت کے ساتھ ذکر کیا ہے، کیونکہ یہاں مذکور مدد اور تعاون کے لئے یہی دونوں صفتیں مناسب ہیں، اس لئے کہ (الولي) اپنے ما تحتوں کے ساتھ حسن سلوک کرتا ہے، اور (الحميد) قابل تعریف چیز عطا کرتا ہے۔ (ابن عاشور: ۲۵؍۹۶)\nاس مقام پر اسماء حسنى میں سب سے زیادہ مناسب (الولي) اور(الحميد) کی صفت ہے، اس کی وضاحت کیجئے؟\nوَمَآ أَصَٰبَكُم مِّن مُّصِيبَةٖ فَبِمَا كَسَبَتۡ أَيۡدِيكُمۡ وَيَعۡفُواْ عَن كَثِيرٖ ٣٠\nاس کا مطلب یہ ہے کہ جو مصیبتیں انسان کو اس کے نفس ومال میں پہنچتی ہیں ان کا سبب گناہ اور معاصی ہوتے ہیں۔(ابن جزی: ۲؍۳۰۳)\nاس شخص کے بارے میں آپ کی کیا رائے ہے جو یہ کہتا ہو کہ دنیا میں جو حوادث ہوتے ہیں ان کے اسباب طبیعی ہیں، اور وہ خود بخود بعض فطری وطبیعی اسباب کی بنا پر وقوع پذیر ہوتے ہیں، نیز گناہ اور معاصی سے ان کا کوئی تعلق نہیں ہے؟\nwords\nإِلاَّ المَوَدَّةَ فِي القُربَىيعني تم اپنے ساتھ قرابت داري كي وجه سے مجھے ميدان دعوت ميں تكليف نه دو.\nيَقتَرِف حَسَنَةًوه نيكي كماتا هے.\nافتَرَىوه جھوٹ گھڑ لايا.\nقَنَطُواوه اس كے نزول سے مايوس هو گئے.\nوَيَنشُرُ رَحمَتَهُوه اپني بارش بھيجتا هے.\nبَثَّاور اس نے متفرق كيا؛ اسے پھيلاديا.\nدَآبَّةٍجو زمين پر چلنے والے انسان وحيوان وغيره."],[487,"§الشورى\ndeeds\nکشتیوں کو دیکھئے کہ کیسے سمندر میں چلتی ہیں، یا پھر اس کی ویڈیو دیکھیں، اور اپنے تاثرات قلمبند کریں، تاکہ آپ صحیح سے اس آیت میں غور کر سکیں.\nجب موذن اذان دے دے تو ہر مشغولیت چھوڑ کر فورا مسجد کی طرف روانہ ہو جائیں.\nاپنے ساتھی سے مشورہ کریں اور اس سے قرآن کی کوئی سورت زبانی یاد کرنے کا بہترین طریقہ پوچھیں.\nguid\nکبیرہ گناہوں سے بچنا اور دور رہنا چاہیئے.\nعفو و درگزر کا مقام ومرتبہ بہت بلند اور عظیم ہے، چنانچہ اس کا اجر اللہ تعالىٰ نے اپنے ذمہ لے لیا ہے.\nہدایت وگمراہی اللہ تعالىٰ کے ہاتھ میں ہے، اس لئے اللہ تعالىٰ سے سوال کریں کہ آپ کو اپنےدین پر ثابت رکھے.\nrefl\nوَمِنۡ ءَايَٰتِهِ ٱلۡجَوَارِ فِي ٱلۡبَحۡرِ كَٱلۡأَعۡلَٰمِ ٣٢ إِن يَشَأۡ يُسۡكِنِ ٱلرِّيحَ فَيَظۡلَلۡنَ رَوَاكِدَ عَلَىٰ ظَهۡرِهِۦٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٍ ٣٣\nکشتی کے سمندر میں چلنے یا اس کے ٹھہرنےکو ہر بکثرت صبر کرنے والے اور زیادہ سے زیادہ شکریہ ادا کرنے والے کےلئے نشانی بنائی گئی ہے، کیونکہ دونوں حالتوں میں خوف اور نجات پایا جاتا ہے، اور خوف صبر کا متقاضی ہے، جبکہ نجات شکر کا تقاضا کرتا ہے۔ (ابن عاشور ۲۵؍۱۰۶)\nسمندر میں کشتیوں کا چلنا اور ٹھہرنا ہر صبرو شکر کرنے والے کے لئے نشانی کیوں ہے؟\nوَإِذَا مَا غَضِبُواْ هُمۡ يَغۡفِرُونَ ٣٧ وَٱلَّذِينَ إِذَآ أَصَابَهُمُ ٱلۡبَغۡيُ هُمۡ يَنتَصِرُونَ ٣٩\nیہ دونوں صفتیں -معاف کرنا اور بدلہ لینا- اپنی اپنی جگہوں پر درست اور پسندیدہ ہیں، چنانچہ ایسا آدمی جو عاجز وکمزور ہو، اور اپنی غلطی کا معترف ہو اسے معاف کردینا پسندیدہ عمل ہے، اور مغفرت کا لفظ اسی کی طرف اشارہ کرتا ہے۔ جبکہ جھگڑالو اور معاند ومصر شخص سے بدلہ لینا بہتر ہے، اور لفظ انتصار اس کی طرف اشارہ کرتا ہے۔اور اگر اس کا الٹا کیا جائے، اور دونوں کی جگہ الٹ دی جائے تو دونوں مذموم اور نا پسندیدہ ہوں گے۔ شاعر نے اپنے اس شعر میں اسی طرف اشارہ کیا ہے: إِذَا أَنْتَ أَکْرَمْتَ الْکَرِيْمَ مَلَکْتَهٗ وَإِنْ أَنْتَ أَکْرَمْتَ اللَّئِيْمَ تَمَرَّدَا فَوَضْعُ النَّدٰى فِيْ مَوْضَعِ السَّيْفِ بِالْعُلَا مُضِرٌّ کَوَضْعِ السَّيْفِ فِيْ مَوضَعِ النَّدٰى (اگر آپ کریم وشریف آدمی کی عزت کریں گے تو آپ اس کے مالک بن جائیں گے، اور وہ آپ کا مطیع وفرمانبردار ہوجائیگا، اور اگر آپ کمینے کی عزت کریں گےتو وہ اور سرکش ہوجائیگا، چنانچہ جس طرح جود و سخا اور عفو و درگزر کی جگہ تلوار استعمال کرنا نقصان دہ ہے، اسی طرح تلوار کی جگہ سخاوت وفیاضی دکھانا اور عفو در گزر کرنا غلط ہے)۔ (الألوسی: ۲۶۶)\nاللہ تعالىٰ کے ان دونوں فرمان: (وإذا ما غضبوا هم يغفرون) ، (والذين إذا أصابهم البغي هم ينتصرون)کے درمیان جمع وتطبیق کی صورت کیسے بنے گی؟\nوَٱلَّذِينَ ٱسۡتَجَابُواْ لِرَبِّهِمۡ وَأَقَامُواْ ٱلصَّلَوٰةَ وَأَمۡرُهُمۡ شُورَىٰ بَيۡنَهُمۡ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ ٣٨\nنماز کو اس کے وقت پر باجماعت پڑھنا، اور زکاۃ ادا کرنا ، یہ اللہ تعالىٰ کے حکم پر لبیک کہنے میں داخل ہے، اسی لئے ان دونوں کو اس پر عطف کیا، اسے عربی زبان میں عطف خاص على عام -یعنی: خاص کو عام پر عطف کرنا- کہا جاتا ہے جو کہ خاص کے شرف وفضیلت پر دلالت کرتا ہے۔ (السعدی: ۷۶۰)\nجب نماز کو اس کے وقت پر باجماعت پڑھنا، اور زکاۃ ادا کرنا، اللہ تعالىٰ کے حکم پر لبیک کہنے میں شامل ہے تو پھر اسے دوبارہ الگ سے کیوں ذکر کیا؟\nوَأَمۡرُهُمۡ شُورَىٰ بَيۡنَهُمۡ\nیعنی: ان میں سے کوئی شخص ایسے معاملات میں جو ان کے درمیان مشترک ہیں استبداد رائے کا مظاہرہ نہیں کرتا، اور تنہا اپنی رائے کو حرف آخر نہیں سمجھتا، بلکہ سب مل جل کر باہمی مشورے سے فیصلہ کرتے ہیں۔ اور یہ چیز ان کے اتحاد واتفاق، باہمی محبت، اور آپسی میل جول کا نتیجہ ہوتی ہے، نیز ان کے عقل کی پختگی پر دلالت کرتی ہے۔ چنانچہ ان کو جب کوئی ایسا معاملہ درپیش آتا ہے جو غور وفکر کرنے کا متقاضی ہے، تو وہ جمع ہو کر آپس میں مشورہ کرتے اور اس کا حل تلاش کرتے ہیں، اور جب حل تک پہنچ جاتے ہیں، اور مصلحت ان پر آشکار ہوجاتی ہے، تو وہ اس کو غنیمت جان کر فورا اس پر عمل پیرا ہوتے ہیں۔ (السعدی: ۷۶۰)\nمسلمانوں کا آپس میں مشورہ کرنا ، ایک عظیم امر پر دلالت کرتا ہے، وہ کیا ہے؟\nوَجَزَٰٓؤُاْ سَيِّئَةٖ سَيِّئَةٞ مِّثۡلُهَاۖ فَمَنۡ عَفَا وَأَصۡلَحَ فَأَجۡرُهُۥ عَلَى ٱللَّهِۚ\nعفو و درگزر میں اللہ تعالىٰ نے یہ شرط لگائی ہے کہ اس سے اصلاح کی امید ہو، چنانچہ اگر مجرم اور گنہگار معافی کا مستحق نہ ہو، اور شرعی مصلحت اس کو سزا دینے کا تقاضہ کرتی ہو، تو ایسی صورت میں معاف کرنے کا حکم نہیں دیاجائیگا۔ (السعدی: ۷۶۰)\nعفو و درگزر کے بعد اصلاح کا ذکر کیوں کیا گیا ہے؟\nوَجَزَٰٓؤُاْ سَيِّئَةٖ سَيِّئَةٞ مِّثۡلُهَاۖ فَمَنۡ عَفَا وَأَصۡلَحَ فَأَجۡرُهُۥ عَلَى ٱللَّهِۚ\nمعاف کرنے والے کا اجر اللہ تعالىٰ کے ذمہ کرنے میں منجملہ حکمتوں میں سے ایک حکمت عفو و درگزر پر ابھارنا ہے، لہذا بندہ مخلوق کے ساتھ ویسا ہی معاملہ اور سلوک کرے جیسا سلوک وہ اللہ تعالىٰ سے اپنے حق میں چاہتا ہے، چنانچہ جس طرح اسے یہ پسند ہے کہ اللہ تعالىٰ اس کے ساتھ عفو درگزر سے کام لے، اسے بھی چاہیئے کہ وہ مخلوق کے ساتھ عفو ودرگزر سے کام لے، اور جس طرح وہ چاہتا ہے کہ اللہ تعالىٰ اس کے ساتھ معافی وتلافی کا معاملہ کرے، اسے بھی چاہیئے کہ وہ مخلوق کے ساتھ ویسا ہی معاملہ کرے۔ (السعدی: ۷۶۰)\nمعاف کرنے والے کا اجر اللہ تعالىٰ کے حوالے کرنے میں کیا فائدہ ہے؟\nوَجَزَٰٓؤُاْ سَيِّئَةٖ سَيِّئَةٞ مِّثۡلُهَاۖ فَمَنۡ عَفَا وَأَصۡلَحَ فَأَجۡرُهُۥ عَلَى ٱللَّهِۚ إِنَّهُۥ لَا يُحِبُّ ٱلظَّٰلِمِينَ ٤٠ وَلَمَنِ ٱنتَصَرَ بَعۡدَ ظُلۡمِهِۦ فَأُوْلَٰٓئِكَ مَا عَلَيۡهِم مِّن سَبِيلٍ ٤١\n(فمن عفا وأصلح فأجره على الله) اس بات پر دلالت کرتا ہے کہ ظالموں کو معاف کر دینا ان سے بدلہ لینے سے افضل ہے، کیونکہ عفو ودرگز کو اجر وثواب کے ساتھ ذکر کیا گیا ہے، اور معافی اللہ تعالىٰ کے یہاں اجر کا ضامن ہے، جبکہ انتقام وبدلے کو اللہ تعالىٰ نے اپنے فرمان: (ولمن انتصر بعد ظلمه فأولئك ما عليهم من سبيل) میں اباحت اور جواز کی تعبیر میں ذکر کیا ہے۔ (ابن جزی: ۲؍۳۰۵)\nعفو درگزر کرنا، انتقام وبدلہ سے کس طرح افضل ہے؟\nwords\nالجَوَارِچلتي هوئي كشتياں.\nكَالأَعلاَمِپهاڑوں كي طرح.\nرَوَاكِدَثابت / ركي هوئي؛ جو چلتي نه هو.\nيُوبِقهُنَّوه كشتيوں كو غرق كركے هلاك كرتا هے.\nمَحِيصٍجائے فرار.\nالبَغيُظلم و عداوت.\nعَزمِ الأُمُورِافعال حميده ؛ او رقابل شكرگزاري خصلتيں."],[488,"§الشورى\ndeeds\nاللہ کے تمام احکام کی پابندی کیجئے خواہ ان کا تعلق کرنے سے ہو یا چھوڑنے سے.\nاپنے گھر والوں کو نصیحت کیجئے، نیز اپنے اور ان کے لئے ہدایت کی دعا کیجئے.\nکسی ایسی آیت یا حدیث کو دیکھیں جس کے حکم کی اتباع میں آپ متردد تھے، اور اس پر عمل کرنے میں جلدی کریں.\nguid\nقیامت کے دن ایک ظالم کا خسارہ کس قدر عظیم ہوگا.\nرسولوں کا مشن دین کی تبلیغ اور اللہ تعالىٰ کی طرف دعوت ہے.\nبندوں کو اللہ تعالىٰ اولاد کی شکل میں جو بھی عطا کرتا ہے اس میں اس کی حکمت پوشیدہ ہوتی ہے، اور وہ اس کے علم کے مطابق ہوتا ہے.\nrefl\nوَتَرَىٰهُمۡ يُعۡرَضُونَ عَلَيۡهَا خَٰشِعِينَ مِنَ ٱلذُّلِّ\nیعنی: اللہ تعالىٰ کی جو نافرمانی انہوں نے ماضی میں کی ہو گی اس کی وجہ سے ان پر ذلت چھائی ہوئی ہوگی۔ (ابن کثیر: ۴؍۱۲۲)\nقیامت کے دن وہ کیوں ذلیل ہوں گے؟\nوَقَالَ ٱلَّذِينَ ءَامَنُوٓاْ إِنَّ ٱلۡخَٰسِرِينَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ وَأَهۡلِيهِمۡ يَوۡمَ ٱلۡقِيَٰمَةِۗ أَلَآ إِنَّ ٱلظَّٰلِمِينَ فِي عَذَابٖ مُّقِيمٖ ٤٥\nرہا ان کے اپنے نفس کا خسارہ تو وہ اس بنا پر کہ وہ جہنم کے عذاب میں مبتلا ہوں گے، اور رہا ان کے گھر والوں کا خسارہ تو وہ اس طرح کہ یا وہ بھی جہنم میں ہوں گے اور ان سے کوئی فائدہ نہیں اٹھا پائیں گے، یا وہ جنت میں تو ہوں گے لیکن ان کے درمیان فاصلہ ہوجائے گا اور ان کے بیچ دیوار حائل کر دی جائے گی۔ (الشوکانی: ۴؍۵۴۳)\nنفس اور اہل وعیال کے خسارے کی کیفیت بیان کیجئے؟\nٱسۡتَجِيبُواْ لِرَبِّكُم مِّن قَبۡلِ أَن يَأۡتِيَ يَوۡمٞ لَّا مَرَدَّ لَهُۥ مِنَ ٱللَّهِۚ مَا لَكُم مِّن مَّلۡجَإٖ يَوۡمَئِذٖ وَمَا لَكُم مِّن نَّكِيرٖ ٤٧\nاس آیت اور اس طرح کی دیگر آیتوں میں مجرد آرزو کی برائی کی گئی ہے، اور بندے کو اس کے ہر معاملے میں موقع سے -جائز- فائدہ اٹھانے کا حکم دیا گیا ہے، کیونکہ تاخیر میں آفتیں چھپی ہوتی ہیں۔ (السعدی: ۷۶۱)\nمذموم آرزو کیا ہے اور کیا عمل کو موخر کرنا درست ہے؟\nفَإِنۡ أَعۡرَضُواْ فَمَآ أَرۡسَلۡنَٰكَ عَلَيۡهِمۡ حَفِيظًاۖ\nیعنی: آپ ان کے اعمال کے نگراں اور محافظ نہیں ہیں کہ ان لوگوں کا ان اعمال پر محاسبہ کریں۔ یہ بھی کہا گیا ہے کہ: آپ ان کے اس طرح ذمہ دار نہیں ہیں کہ جب تک وہ ایمان نہ لے آئیں آپ ان کے پیچھے پڑے رہیں ۔ یعنی: آپ انہیں ایمان لانے کے لئے زبردستی نہیں کرسکتے۔ (القرطبی: ۱۸؍۵۰۰)\nداعی کی دعوت پر اگر مدعو لبیک نہ کہے تو ایسی حالت میں اس کے لئےاس آیت میں دلاسہ اور تسلی ہے، اس کی وضاحت کیجئے؟\nوَإِنَّآ إِذَآ أَذَقۡنَا ٱلۡإِنسَٰنَ مِنَّا رَحۡمَةٗ فَرِحَ بِهَاۖ وَإِن تُصِبۡهُمۡ سَيِّئَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ فَإِنَّ ٱلۡإِنسَٰنَ كَفُورٞ ٤٨\nاس آیت میں اس بات کی طرف اشارہ ہے کہ رحمت کا نزول خوشی منانے اور تکبر کرنے کے لئے نہیں ہوتا، بلکہ اسے عطا کرنے والے کا شکریہ ادا کرنے کے لئے ہوتا ہے۔ اسی طرح آزمائش اور پریشانی کا آنا کفران نعمت اور جزع فزع کے لئے نہیں، بلکہ اس لئے ہوتا ہے کہ جس کی طرف سے وہ چیز آئی ہے اس کی طرف رجوع کیا جائے، یعنی: اللہ تعالىٰ کی طرف لوٹا جائے، اور اس سے اس کو دور کرنے کا سوال کیا جائے۔ (الألوسی: ۲۵؍۷۵)\nاچھی اور بری دونوں حالتوں میں ایک مومن بندے پر کیا کرنا واجب ہے؟\nوَإِن تُصِبۡهُمۡ سَيِّئَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ فَإِنَّ ٱلۡإِنسَٰنَ كَفُورٞ ٤٨\nیعنی: جو نعمتیں اس پر گزر چکی ہیں اور جن نعمتوں سے وہ ماضی میں محظوظ ہو چکا ہے ان کو بھول کر ان کا انکار کرنے لگتا ہے، اور اسے صرف موجودہ -پریشانی کی- حالت یاد رہ جاتی ہے۔ (ابن کثیر: ۴؍۱۲۲-۱۲۳)\nگزشتہ نعمتوں کا خیال رکھنے میں مومن اور کافر کے درمیان کیا فرق ہے؟\nلِّلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ يَخۡلُقُ مَا يَشَآءُۚ يَهَبُ لِمَن يَشَآءُ إِنَٰثٗا وَيَهَبُ لِمَن يَشَآءُ ٱلذُّكُورَ ٤٩\nاس کی تفسیر میں کہا گیا ہے : عورتوں کا ذکر اس لئے پہلے ہے تاکہ ان کی کمزوری کا خیال کرتے ہوئے ان کے دیکھ بھال کی خصوصی وصیت کی جائے، خاص طور سے اس لئے بھی کہ ابھی کچھ دنوں پہلے تک -زمانہ جاہلیت میں- انہیں زندہ درگور کر دیا جاتا تھا۔ نیز حدیث شریف میں آیا ہے کہ: “جسے اللہ تعالىٰ نے ان بچیوں کے ذریعہ آزمایا، اور اس نے ان کے ساتھ حسن سلوک کیا، تو قیامت کے دن وہ اس کے لئے جہنم کی آگ سے اوٹ اور پردہ ہوں گی”۔ (الألوسی: ۲؍۷۵-۷۶)\nاس آیت اور حدیث کی روشنی میں یہ وضاحت کیجئے کہ کس طرح اسلام نے عورت کی تکریم اور اس کی حفاظت کی ہے؟\nwords\nيَنظُرُونَ مِن طَرفٍ خَفِيٍّوه نظريں چرا كر ديكھتے.\nلا مَرَدَّ لَهُان كے ليے اس كا رد كرنا ممكن نهيں.\nنَكِيرٍتم اپنے گناهوں كاانكار نهيں كرتے/ تم كهيں چھپ بھي نهيں سكتے.\nعَقِيمًاجس كے هاں بچه نه هوسكتا هو.\nمِن وَرَاءِ حِجَابٍپرده كے پيچھے سے (جيسے حضرت موسي عليه السلام نے كلام كيا)."],[489,"§الشورى ، الزخرف\ndeeds\nتین ایسے دنیاوی یا اخروی فوائد نوٹ کیجئے جو قرآن میں غورو فکر کے نتیجہ میں آپ کے اندر بیدار ہوئے ہیں.\nآپ تصور کیجئے! کہ اگر قرآن آپ تک نہ پہنچا ہوتا اور اسلام کی ہدایت نہ ملتی تو آپ کیسی پرمشقت اور بدبختی والی زندگی جی رہے ہوتے، پھر ایمان و ہدایت کی نعمت پر اللہ کا شکر ادا کیجئے.\nانبیاء کرام کی عظمت و فضیلت پرایک مقالہ لکھئے یا اس بارے میں اپنے بھائیوں کو خطاب کیجئے.\nguid\nآپ صلی اللہ علیہ وسلم کی اتباع ان اسباب میں سے ہے جن سے انسان صراط مستقیم کی طرف ہدایت پاتا ہے.\nتمام معاملات کا مرجع وماوى اللہ تعالىٰ ہی کی ذات ہے، اور سارے امور اسی کی طرف لوٹ کر جانے والے ہیں، اس لئے اسی پر بھروسہ کیجئے.\nبسا اوقات حد سے زیادہ غافل اگر ہدایت پاجائے تویہ شخص مسلمانوں کے لئے دوسروں کی بنسبت زیادہ نفع بخش ہوتا ہے.\nrefl\nوَكَذَٰلِكَ أَوۡحَيۡنَآ إِلَيۡكَ رُوحٗا مِّنۡ أَمۡرِنَاۚ\nیہاں روح سے مراد قرآن ہے۔ اور قرآن کو روح اس لئے کہا گیا ہے کیونکہ انسان اس کے ذریعہ جہالت کی موت سے نکل کر علم کی زندگی میں داخل ہوجاتا ہے۔ مالک بن دینار کہا کرتے تھے: اے اہل قرآن! قرآن نے تمہاے دلوں میں کیا بویا ہے؟ بیشک قرآن دلوں کے لئے بہار ہے، جس طرح بارش زمین کے لئے بہار ہے۔ (القرطبی ۱۸؍۵۰۹)\nقرآن کو روح کا نام دینے میں کسى چیز پر ابھارنا مقصود ہے، اسی طرح اس میں ایک بلیغ دلالت پنہاں ہے، اس کی وضاحت کیجئے؟\nمَا كُنتَ تَدۡرِي مَا ٱلۡكِتَٰبُ وَلَا ٱلۡإِيمَٰنُ\nیہاں اللہ تعالىٰ نے وحی سے قبل اپنے رسول صلی اللہ علیہ وسلم کی صفت بیان کرتے ہوئے کہا ہے: (ما كنت تدري ما الكتاب) یعنی: وہ کیا چیز ہے؟اس لئے کہ آپ صلی اللہ علیہ وسلم امی تھے، نہ پڑھنا جانتے تھے، اور نہ ہی لکھنا۔ اور یہ چیز اعجازِ قرآن -معجزہ- کے لئے زیادہ قوى اور مناسب ہے، اور آپ صلی اللہ علیہ وسلم کى نبوت کے صحیح ہونے پر زیادہ قوت سے دلالت کرنے والى ہے۔ (الشوکانی: ۴؍۵۴۵)\nیہ آیت آپ صلی اللہ علیہ وسلم کى نبوت کے صحیح ہونے پر دلالت کرتی ہے، اس کی وضاحت کیجئے؟\nوَلَٰكِن جَعَلۡنَٰهُ نُورٗا نَّهۡدِي بِهِۦ مَن نَّشَآءُ مِنۡ عِبَادِنَاۚ وَإِنَّكَ لَتَهۡدِيٓ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ٥٢\nیہاں قرآن کو نور- روشنی- سے تشبیہ دیا گیا ہے، کیونکہ ہدایت و رہنمائی میں دونوں مشترک ہیں، یہی وجہ ہے کہ ایمان، ہدایت ورہنمائی، اور علم تینوں کو نور سے تشبیہ دی جاتی ہے، جبکہ ضلات وگمراہی، جہالت، اور کفر کو ظلمت وتاریکی سے تشبیہ دی جاتی ہے، اللہ تعالىٰ کا ارشاد ہے: ﴿يُخۡرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ﴾ [البقرة: ٢٥٧]۔ چنانچہ جب حالت یہ ہے کہ تاریکی میں چلنے والا راستے سے بھٹک جاتا ہے، اور جب اسے روشنی ملتی ہے تو پھر راستہ پاتا ہے، تو گویا روشنی ہى ہدایت ورہنمائی کا وسیلہ ہے، ہاں البتہ روشنی سے رہنمائی وہی پاتا ہے جس کے اور روشنی کے درمیان کو ئی چیز حائل نہ ہو، ورنہ ہدایت کا کوئی وسیلہ اسے فائدہ نہیں پہنچا سکتا،اسی لئے اللہ تعالىٰ نے کہا: (نهدي به من نشاء من عبادنا) (ابن عاشور ۲۵؍۱۵۴)\nقرآن کو روشنی سے کیوں تشبیہ دیا گیا؟ اور قرآن کریم کی روشنی سے کون فائدہ اٹھا سکتا ہے؟\nوَإِنَّهُۥ فِيٓ أُمِّ ٱلۡكِتَٰبِ لَدَيۡنَا لَعَلِيٌّ حَكِيمٌ ٤\nفرشتوں کی بزرگ وبرتر اور اعلى وبلند ترین مقام والى جماعت میں قرآن کریم کی قدر ومنزلت اور اس کے شرف کی یہاں وضاحت کردی، تاکہ زمین میں بسنے والے لوگ بھی اس کی قدر ومنزلت کو پہچانیں، اور عظیم سمجھیں، اور اس کی فرمانبرداری کریں۔ (ابن کثیر ۴؍۱۲۴)\nاللہ تعالىٰ نے فرشتوں کی اعلى ترین جماعت کے یہاں اس کتاب کی قدر ومنزلت اور اس کے مقام ومرتبہ کو کیوں واضح کیا؟\nأَفَنَضۡرِبُ عَنكُمُ ٱلذِّكۡرَ صَفۡحًا أَن كُنتُمۡ قَوۡمٗا مُّسۡرِفِينَ ٥\nقتادہ نے فرمایا: اللہ کی قسم جس وقت اس امت کے ابتدائی لوگوں -کفار مکہ- نے اس کتاب کو ٹھکرا دیا تھا اگر یہ کتاب اٹھا لی جاتی، تو روئے زمین پر بسنے والے تمام لوگ ہلاک وبرباد ہو جاتے، مگر اللہ تعالىٰ نے اپنے فضل وکرم سے اسے ان پر بار بار تکرار کے ساتھ دہرایا ۔ (القرطبی ۱۹؍۷)\nجب نزولِ قرآن کے ابتدائی ایام میں لوگوں نے اس قرآن کو ٹھکرا دیا تھا اگر اسی وقت اسے اٹھا لیا جاتا تو ہماری کیا حالت ہوتی؟\nأَفَنَضۡرِبُ عَنكُمُ ٱلذِّكۡرَ صَفۡحًا أَن كُنتُمۡ قَوۡمٗا مُّسۡرِفِينَ ٥\nاگر چہ تمہاری حالت اس بات کا تقاضا کرتی ہے کہ تمہیں تمہاری حالت پر چھوڑ دیا جائے یہاں تک کہ تم ضلالت وگمراہی کی حالت میں مر جاؤ، اور پھر ہمیشہ ہمیش عذاب میں رہو، مگر ہم اپنی کشادہ رحمت کی وجہ سے ایسا نہیں کر سکتے، بلکہ ہم امانت دار رسول بھیج کر اور واضح کتاب نازل فرما کر حق کی طرف تمہاری رہنمائی کریں گے۔ (الألوسی: ۲۵؍۹۰)\nیہ آیت اللہ تعالىٰ کی کشادہ رحمت اور اس کے فضل وکرم پر کس طرح دلالت کرتی ہے؟\nوَمَا يَأۡتِيهِم مِّن نَّبِيٍّ إِلَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ ٧\nاللہ تعالىٰ یہاں اپنے پیارے نبی محمد صلی اللہ علیہ وسلم کی تعزیت کر رہا ہے، اور آپ صلی اللہ علیہ وسلم کو تسلی دے رہا ہے۔ (القرطبی: ۱۹؍۹)\nگزشتہ انبیاء کرام علیہم السلام کے ساتھ ان کی قوموں کے خراب سلوک اور ان کے استہزاء کو ذکر کرنے کا کیا مقصد ہے؟\nwords\nرُوحًاقرآن / اس ليے اسے روح كها كه اس ميں دلوں كي زندگي هے.\nصِرَاطٍ مُستَقِيمٍسيدھا راسته / مراد اسلام هے.\nتَصِيرُوه اس كي طرف رجوع كرتا هے/ وه اس پر جزاء ديتا هے.\nأُمِّ الكِتَابِلوح محفوظ.\nأَفَنَضرِبُ عَنكُمُ الذِّكرَ صَفحًاكيا هم تم سے منه موڑتے هيں۔ اور تمهارا قرآن كے ذريعه وعظ بھول جاتے هيں."],[490,"§الزخرف\ndeeds\nاللہ تعالىٰ کی بعض نعمتوں کو یہ کہتے ہوئے شمار کیجئے کہ: اللہ تعالىٰ نے مجھ پر یہ یہ نعمتیں کر رکھی ہیں، پھر ان پر اللہ تعالىٰ کا شکریہ ادا کیجئے.\nجب آپ گاڑی،جہاز،کشتی،لفٹ،جانور پر سوار ہوں تو یہ دعا پڑھیں.\nکسی ایسى عبادت پر نظر ڈالئے جو آپ کے والدین میں سے کوئی کر رہا ہو، اسے آپ بھی انجام دیجئے، اور ان دونوں کے لئے دعا کیجئے، اسی طرح کسی ایسے غلط عمل کو دیکھئے جو ان دونوں میں سے کوئی کر رہا ہو، اس سے بچئے، اور ان دونوں کی ہدایت کے لئے دعا کیجئے.\nguid\nاللہ تعالىٰ کی تعظیم کا تقاضہ یہ بھی ہے کہ صرف اس کی عبادت کی جائے.\nاللہ تعالىٰ کے یہاں فرشتوں کا مقام ومرتبہ بلند اور عظیم ہے.\nایک بہت بڑی چیز جوانسان کو اللہ تعالىٰ سے دور کردیتی اور اس کے راستے سے روک دیتی ہے وہ باپ داد ا کی غلط تقلید،غلط عادات وتقالید اور رسوم ورواج کی پیروی ہے جبکہ وہ کتاب اللہ اور سنت رسول صلی اللہ علیہ وسلم کے خلاف ہوں.\nrefl\nوَٱلَّذِي نَزَّلَ مِنَ ٱلسَّمَآءِ مَآءَۢ بِقَدَرٖ فَأَنشَرۡنَا بِهِۦ بَلۡدَةٗ مَّيۡتٗاۚ\nابن عباس رضی اللہ عنہ نے فرمایا: یعنی: بلا اندازہ قوم نوح کی طرح نہیں نازل کیا یہاں تک کہ وہ غرق ہوگئے، بلکہ ایک مناسب اندازے سے نازل کیا، چنانچہ نہ ہی ایسى طوفانی بارش بھیجی کہ غرق کردے، اور نہ ہی ضرورت سے کم نازل کیا، تاکہ تمہارے اور تمہارے چوپایوں کے لئے رزق کا سامان ہو۔ (القرطبی: ۱۹؍۱۱)\nپانی کے نزول کے تئیں (بقدر) یعنی: ایک اندازے سے- کہنے میں کیا راز پنہاں ہے؟\nوَٱلَّذِي نَزَّلَ مِنَ ٱلسَّمَآءِ مَآءَۢ بِقَدَرٖ فَأَنشَرۡنَا بِهِۦ بَلۡدَةٗ مَّيۡتٗاۚ كَذَٰلِكَ تُخۡرَجُونَ ١١\nزمین کی پیدائش سے استدلال، اور اس پر احسان جتلانے کے بعد اللہ تعالىٰ نے زندگی گزارنے کے لئے جو مختلف وسائل پیدا کئے ہیں ان سے استدلال کیا، اور احسان جتلایا، اور وہ پانی ہے جس کیوجہ سے زمین لوگوں کے لئے صالح اور مناسب رزق اگاتی اور غذا کا سامان کرتی ہے۔ (ابن عاشور ۲۵؍۱۷۰)\nقرآن دلائل کو پیش کرنے میں تدریج و ترتیب سے کام لیتا ہے، اس آیت کى روشنی میں اس کی وضاحت کیجئے؟\nوَجَعَلَ لَكُم مِّنَ ٱلۡفُلۡكِ وَٱلۡأَنۡعَٰمِ مَا تَرۡكَبُونَ ١٢ لِتَسۡتَوُۥاْ عَلَىٰ ظُهُورِهِۦ ثُمَّ تَذۡكُرُواْ نِعۡمَةَ رَبِّكُمۡ إِذَا ٱسۡتَوَيۡتُمۡ عَلَيۡهِ وَتَقُولُواْ سُبۡحَٰنَ ٱلَّذِي سَخَّرَ لَنَا هَٰذَا وَمَا كُنَّا لَهُۥ مُقۡرِنِينَ ١٣ وَإِنَّآ إِلَىٰ رَبِّنَا لَمُنقَلِبُونَ ١٤\n(وإنا إلى ربنا لمنقلبون)، یعنی: ہم مرنے کے بعد اسی -اللہ -کی طرف جانے والے ہیں، اور ہمارا حتمی چلنا اسی کی طرف ہوگا۔ اور یہ دنیاوی سفر سے اخروى سفر کی طرف توجہ دلانا ہے، جیسا کہ اللہ تعالىٰ کے فرمان: ﴿وَتَزَوَّدُواْ فَإِنَّ خَيۡرَ ٱلزَّادِ ٱلتَّقۡوَىٰ﴾ [البقرة: ١٩٧] (یعنی: توشہ اختیار کرو، پس بیشک بہترین توشہ تقوى کا توشہ ہے) میں دنیاوی توشے سے اخروی توشے کی طرف توجہ دلائی گئى ہے۔ اور اللہ تعالىٰ کے فرمان: ﴿وَرِيشًاۖ وَلِبَاسُ ٱلتَّقۡوَىٰ ذَٰلِكَ خَيۡرٌ﴾ [الأعراف: ۲۶]، (یعنی: اور تقوى کا لباس یہ زیادہ بہتر ہے)میں دنیوى لباس کے ذریعہ اخروی لباس کی طرف توجہ دلائی گئی ہے۔ (ابن کثیر ۴؍۱۲۶)\nکتنی ہی دفعہ دنیاوی امور ہمیں اخروی امور کی طرف رہنمائی کرتے ہیں۔ ان آیتوں کی روشنی میں اس کی وضاحت کیجئے؟\nوَإِنَّآ إِلَىٰ رَبِّنَا لَمُنقَلِبُونَ ١٤\nیعنی: ہم لوٹنے والے ہیں، اس میں اس بات کی طرف اشارہ ہے سوار اپنے چلنے اور سفر سے متعلق چیزوں پر غور کرے، اور اس سے وہ بڑا سفر یاد کرے جس میں وہ اللہ تعالىٰ کی طرف روانہ ہوگا، اس طرح وہ اِس سفر سے اُس سفر کے معاملات درست اور مرتب کرے، اور ایسا کام نہ کرے جو اس کے مخالف اور منافی ہو، اور اس بات کا تقاضہ یہ ہے کہ اس کا یہ سفر کسی شرعی اور درست کام کے لئے ہو۔ اسی طرح اس میں اس بات کی طرف بھی اشارہ ہے کہ سفر ایک پر خطر چیز ہے، لہذا اس میں آخرت کو پیش نظر رکھے اور اس کی یاد سے غافل نہ ہو۔ (الألوسی:۲۵؍۹۶)\nسواری پر سوار ہونا، سفر کرنا، یا اس طرح کی چیزیں کس طرح آخرت کی یاد دلاتی ہیں؟\nلِتَسۡتَوُۥاْ عَلَىٰ ظُهُورِهِۦ ثُمَّ تَذۡكُرُواْ نِعۡمَةَ رَبِّكُمۡ إِذَا ٱسۡتَوَيۡتُمۡ عَلَيۡهِ وَتَقُولُواْ سُبۡحَٰنَ ٱلَّذِي سَخَّرَ لَنَا هَٰذَا وَمَا كُنَّا لَهُۥ مُقۡرِنِينَ ١٣ وَإِنَّآ إِلَىٰ رَبِّنَا لَمُنقَلِبُونَ ١٤\nمسلم شریف کی روایت ہے کہ آپ صلی اللہ علیہ وسلم جب اپنی سواری پر سوار ہوتے تو تین بار اللہ اکبر کہتے، پھر فرماتے:(سبحان الذي سخر لنا هذا وما كنا له مقرنين * وإنا إلى ربنا لمنقلبون) پھر اس کے بعد کہتے: «اللهم إني أسألك في سفري هذا البِرَّ والتقوى، ومن العمل ما ترضى. اللهم هَوِّن علينا السفر واطوِ لنا البعيد. اللهم أنت الصاحب في السفر والخليفة في الأهل. اللهم اصحبنا في سفرنا واخلفنا في أهلنا»،اور جب سفر سے اپنے گھر لوٹتے تو کہتے: «آيبون تائبون إن شاء الله، عابدون، لربنا حامدون». البقاعي:۷/۱۳.\nاس آیت پر عمل کس طرح ہوگا؟\nأَمِ ٱتَّخَذَ مِمَّا يَخۡلُقُ بَنَاتٖ وَجَعَلُواْ ٱلۡمَلَٰٓئِكَةَ ٱلَّذِينَ هُمۡ عِبَٰدُ ٱلرَّحۡمَٰنِ إِنَٰثًاۚ\nان لوگوں -کفار ومشرکین- نے فرشتوں پر کس قدر جرأت کی اور انہیں عبودیت اور تذلل کے مرتبہ سے اٹھا کر ایسی جگہ پہنچا دیا جو اللہ تعالیٰ کے شایان شان ہے،پھر ان کا مرتبہ مذکر سے گھٹا کر انھیں عورتوں کی صف میں شامل کردیا۔ پس اللہ تعالیٰ کی ذات کتنی پاک ہے جس نے اس کی ذات پر جھوٹ گڑھنے والوں اور اس کے رسولوں کی مخالفت کرنے والوں کے تناقض کو ظاہر کردیا۔ (السعدی: ۷۶۴)\nمشرکوں کی بات میں واضح تناقض ہے، اس کی وضاحت کیجئے؟\nأَوَ مَن يُنَشَّؤُاْ فِي ٱلۡحِلۡيَةِ وَهُوَ فِي ٱلۡخِصَامِ غَيۡرُ مُبِينٖ ١٨\nزیب و زینت اور نزاکت میں پلنا اور پرورش پانا منجملہ عیب دار اور نا پسندیدہ امور میں سے ہے، اور یہ عورتوں کی صفات میں سے ہے، اور انہیں کے لئے لائق اور زیبا ہے۔ اس لئے مردوں کو اس سے بچنا اور دور رہنا چاہیئے، اور اس طرح زندگی گزارنی چاہیئے جیسا کی عمر رضی اللہ عنہ نے رہنمائی کرتے ہوئے فرمایا: پہننے اور کھانے میں سادگی اختیار کرو، اور سادی زندگی گزارو،اور اگر کوئی شخص اپنے نفس کو مزین کرنا چاہے تو تقوىٰ کے لباس سے اپنے باطنی نفس کو مزین کرے۔ (الألوسی: ۲۵؍۹۹)\nکیا زیب و زینت میں غلو کرنا، اور نزاکت اختیار کرنا مردوں کو زیبا دیتا ہے؟ اور کیوں؟\nwords\nبِقَدَرٍمقدار ؛ معلوم وزن.\nمُقرِنِينَطاقت ركھنے والے.\nوَأَصفَاكُمتمهيں خاص كيا هے.\nكَظِيمٌغم و حزن سے بھرا هوا.\nيُنَشَّأُوه تربيت كرتا هے؛ بڑھاتا هے.\nالحِليَةِزينت / زيور."],[491,"§الزخرف\ndeeds\nعیش وآرام کے ایسے اسباب ووسائل جو آپ کو حرام کا ارتکاب کرنے یا واجب کو چھوڑنے پر آمادہ کرتے ہوں انہیں اپنى زندگی سے ختم کرنے کے لئے ایک پلان ترتیب دیجئے.\nابراہیم علیہ السلام نے توحید کو کیسے پورا کیا اس کے تین مظاہر اور نمونے لکھئے.\nاللہ تعالىٰ نے بندوں کو ایک دوسرے کے لئے کس طرح مسخر کر رکھا ہے اس کا کوئی نمونہ جو آج آپ کے سامنے پیش آیا ہو اسے نوٹ کیجئے.\nguid\nعیش وعشرت تکبر پیدا کرنے،اور حق سے دور کرنے والے منجملہ اسباب میں سے ہے۔ لہٰذا متنبہ رہئے.\nآپ یہ بات ذہن نشین کرلیں کہ دعوت کا کام کرنے والے کا مذاق اڑایا جاتا ہے، اور اس کے ساتھ استہزاء کیا جاتا ہے، اس لئے یہ چیز آپ کے لئے تکلیف کا باعث نہیں بننی چاہیئے.\nیہ اللہ تعالىٰ کی رحمت میں سے ہے کہ اس نے بعض کو بعض کےتابع کردیا ہے، اور لوگوں کو ایک دوسرے کے لئے مسخر کردیا ہے، فقیر کو غنی کا، اور غنی کو فقیر کا محتاج بنا دیا ہے.\nrefl\nوَإِذۡ قَالَ إِبۡرَٰهِيمُ لِأَبِيهِ وَقَوۡمِهِۦٓ إِنَّنِي بَرَآءٞ مِّمَّا تَعۡبُدُونَ ٢٦\nجب اللہ تعالىٰ نے ان کے لئے دلائل کو ذکر کیا، انہیں اپنی گرفت سےڈرایا، اور یہ بات عیاں ہوگئی کہ وہ تقلید نہیں چھوڑ سکتے، تو ایسے وقت میں اللہ تعالىٰ نے انہیں ان کے عظیم ترین اور قابل فخر باپ -ابراہیم علیہ السلام- کا ذکر کرکے نصیحت کی جو درحقیقت اتباع کے زیادہ حق دار اور پیروی کے زیادہ لائق ہیں، تاکہ وہ یا تو اپنے اِس باپ کی طرح تقلید چھوڑ کر کامیاب ہو جائیں، یا پھر اگر وہ تقلید کو اتنا ہی ضروری سمجھتے ہیں تو اسی باپ کی تقلید کریں، اس لئے کہ یہ باپ -ابراہیم علیہ السلام- ان کے آباء واجداد میں سب سے عظیم ہے، اور ساتھ ہی ساتھ اس کے پاس دلیل بھی ہے۔ (البقاعی: ۷؍۲۱)\nوہ مشرکین جو اپنے باپ دادا کے دین کو مضبوطی سے پکڑے ہوئے تھے ان کے ذکر کے بعد ابراہیم علیہ السلام کا قصہ کیوں ذکر کیا گیا؟\nوَإِذۡ قَالَ إِبۡرَٰهِيمُ لِأَبِيهِ وَقَوۡمِهِۦٓ إِنَّنِي بَرَآءٞ مِّمَّا تَعۡبُدُونَ ٢٦\nابراہیم علیہ السلام کی اس چیز سے براءت جس کی ان کے والد پوجا کرتے تھے، یہ بت پرستی سے بچنے اور دور رہنے پر زیادہ قوت سے دلالت کرتی ہے کہ ان کے یہاں اس سلسلے میں کوئی نرمی نہیں تھی، اگر چہ ان بتوں کو پوجنے والا باپ کی شکل میں اس عظیم موحد -ابراہیم علیہ السلام- کا قریب ترین رشتہ دار ہی کیوں نہ ہو۔ (ابن عاشور: ۲۵؍۱۹۲ )\nقوم کے ذکر سے پہلے ابراہیم علیہ السلام کے باپ کا خصوصی طور سے کیوں ذکر کیا گیا ہے؟\nوَجَعَلَهَا كَلِمَةَۢ بَاقِيَةٗ فِي عَقِبِهِۦ لَعَلَّهُمۡ يَرۡجِعُونَ ٢٨\n(وجعلها) یعنی: اس بہترین خصلت کو جو تمام خصلتوں کی جڑ اور بنیاد ہے۔ایسا بنا دیا کہ وہ آنے والی نسلوں میں باقی رہے اور وہ خصلت صرف ایک اللہ کی عبادت اور اس کے علاوہ کی عبادت سے براءت ہے۔ چنانچہ یہ کلمہ ان کی ذریت میں باقی رہا یہاں تک کہ وہ عیش وعشرت کے شکار ہو گئے، اور ان میں سرکشی آگئی۔ (السعدی: ۷۶۴)\nعیش و عشرت اور سرکشی کا عقیدہ توحید پر کیا اثر پڑتا ہے؟\nوَلَمَّا جَآءَهُمُ ٱلۡحَقُّ قَالُواْ هَٰذَا سِحۡرٞ وَإِنَّا بِهِۦ كَٰفِرُونَ ٣٠\nیہ عناد اور مخالفت نیز سرکشی کی عظیم شکل ہے کہ انھوں نے محض اعراض ونافرمانی اور جحود وانکار پر اکتفا نہیں کیا، بلکہ انھیں اس وقت تک سکون نہیں ملا جب تک انھوں نے اس پر سنگین ترین الزام نہیں لگا دیا، اور اس کو اس باطل جادو کے زمرے میں داخل کردیا جسے سب سے جھوٹا اور خبیث ترین شخص انجام دیتا ہے۔ (السعدی: ۷۶۵)\nآپ کو مشرکین کے اس قول: (هذا سحر) سے ان کی کس حالت کا پتہ چلتا ہے؟\nوَقَالُواْ لَوۡلَا نُزِّلَ هَٰذَا ٱلۡقُرۡءَانُ عَلَىٰ رَجُلٖ مِّنَ ٱلۡقَرۡيَتَيۡنِ عَظِيمٍ ٣١ أَهُمۡ يَقۡسِمُونَ رَحۡمَتَ رَبِّكَۚ نَحۡنُ قَسَمۡنَا بَيۡنَهُم مَّعِيشَتَهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ\nجب بندوں کی معیشت کے اسباب اور ان کے دنیاوی ارزاق اللہ تعالىٰ کے ہاتھ میں ہیں، وہی انھیں بندوں میں تقسیم کرتا ہے، چنانچہ اپنی حکمت سے جس کو چاہتا ہے کشادہ رزق عطا کرتا ہے، اور جسے چاہتا ہے تنگی دیتا ہے۔ تو اس کی دینی رحمتیں جن کا اعلى ترین حصہ نبوت ورسالت ہے وہ اس بات کے زیادہ لائق ہیں کہ اللہ تعالىٰ کے ہاتھ میں رہیں، پس اللہ تعالىٰ زیادہ بہتر جانتا ہے کہ وہ اپنی رسالت کہاں رکھے، اور کسے عطا کرے؟ چنانچہ یہاں یہ بات واضح ہوگئی کہ ان -کفار ومشرکین- کى رائے اور ان کا مشورہ باطل اور لا یعنی وبے وقعت ہے، اور سارے دینی ودنیوی معاملات کی تدبیر کرنا اور اسے چلانا صرف اللہ تعالىٰ کے ہاتھ میں ہے۔ (السعدی: ۷۶۵)\nیہاں اللہ تعالىٰ نے کفار ومشرکین کے اس مشورے کہ “قرآن کو دونوں بستیوں کے کسی عظیم شخص پر کیوں نہیں اتارا گیا” کے بعد رزق کی تقسیم کا کیوں ذکر کیا؟\nوَرَفَعۡنَا بَعۡضَهُمۡ فَوۡقَ بَعۡضٖ دَرَجَٰتٖ لِّيَتَّخِذَ بَعۡضُهُم بَعۡضٗا سُخۡرِيّٗاۗ وَرَحۡمَتُ رَبِّكَ خَيۡرٞ مِّمَّا يَجۡمَعُونَ ٣٢\n(سخريا) کا مطلب خدمت وعمل میں تابع کرنا اور مسخر بنانا ہے۔ یعنی: ہم نے بعض کو بعض سے بڑا اور اونچا مرتبہ والا بنایا ہے تاکہ لوگ ایک دوسرے کی خدمت کریں۔ (ابن جزی: ۲؍۳۱۲)\nلوگوں کے مقام ومرتبہ میں اختلاف، اور ان کے دنیاوی مراتب میں تفاوت کا ہونا، اس میں بڑی حکمت پوشیدہ ہے۔ وہ حکمت کیا ہے؟\nوَلَوۡلَآ أَن يَكُونَ ٱلنَّاسُ أُمَّةٗ وَٰحِدَةٗ لَّجَعَلۡنَا لِمَن يَكۡفُرُ بِٱلرَّحۡمَٰنِ لِبُيُوتِهِمۡ سُقُفٗا مِّن فِضَّةٖ وَمَعَارِجَ عَلَيۡهَا يَظۡهَرُونَ ٣٣\nحسن نے فرمایا: اس کا معنى یہ ہے کہ اگر یہ بات نہ ہوتی کہ دنیا کی طرف مائل ہونے اور آخرت سے بے رغبتی برتنے کے سبب سارے لوگ کافر ہو جائیں گے، تو ہم انھیں دنیا میں یہ چیزیں عطا کر دیتے۔ اس لئے کہ دنیا اللہ تعالىٰ کے یہاں بہت حقیر اور کم تر ہے۔ (القرطبی: ۱۹؍۳۷-۳۸)\nاس آیت کی روشنی میں اللہ تعالىٰ کے یہاں دنیا کی حقارت بیان کیجئے؟\nwords\nبَرَاءٌبري هيں.\nفَطَرَنِياس نے مجھے پيدا كيا.\nسُخرِيًّاعمل كے ليے مسخر.\nوَمَعَارِجَچاندي كي سيڑھياں.\nيَظهَرُونَوه چڑھتے هيں."],[492,"§الزخرف\ndeeds\n(سُبْحَانَ اللّٰهِ وَبِحَمْدِهٖ، سُبْحَانَ اللّٰهِ الْعَظِيْم) سو (۱۰۰) مرتبہ کہیئے.\nکسى متروک ومہجور سنت کی معرفت حاصل کیجئے، اور اس کو لازم پکڑیئے.\nکسی ایسے لمبے وقت کو یاد کیجئے جس میں آپ نے اللہ تعالىٰ کو نہ یاد کیا ہو، پھر اس آیت کے تناظر میں سوچئے کہ اس وقت شیطان آپ کا ساتھی رہا ہوگا.\nguid\nکسی ایسے عمل سے بچیں جس کے بارے میں آپ کا گمان ہو کہ آپ راہ ہدایت پر ہیں، جبکہ حقیقت میں آپ گمراہی کا شکار ہوں، اور جان لیں کہ اس کا علاج صحیح دلیل کی معرفت میں مضمر ہے.\nکتاب وسنت کو لازم پکڑیں، اور جان لیں کہ یہی دونوں غلطی سے پاک اور مبرا ہیں، اور ان ہی میں دنیا وآخرت میں نجات مضمر ہے.\nدین اور دین داروں کا مذاق اڑانا کفار ومنافقین کی صفات میں سے ہے.\nrefl\nلَّجَعَلۡنَا لِمَن يَكۡفُرُ بِٱلرَّحۡمَٰنِ لِبُيُوتِهِمۡ سُقُفٗا مِّن فِضَّةٖ وَمَعَارِجَ عَلَيۡهَا يَظۡهَرُونَ ٣٣ وَلِبُيُوتِهِمۡ أَبۡوَٰبٗا وَسُرُرًا عَلَيۡهَا يَتَّكِـُٔونَ ٣٤ وَزُخۡرُفٗاۚ وَإِن كُلُّ ذَٰلِكَ لَمَّا مَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ\nیعنی: ان کی دنیا کو مختلف قسم کی زیب وزینت سے مزین وآراستہ کردیتا،اور انھیں ان کے حسب خواہش عطا کردیتا،لیکن بندوں کے ساتھ اس کا رحم وکرم اس سے مانع ہے، کیونکہ یہ ڈر ہے کہ دنیا سے محبت کی وجہ سے وہ بہت تیزی سے کفر ومعصیت میں واقع ہوجائیں گے۔ چنانچہ اس میں اس بات کی دلیل ہے کہ اللہ تعالىٰ اپنے بندوں کو بہت سی چیزیں عمومی یا خصوصی طور پر صرف اس لئے نہیں دیتا ہے کہ اس میں خود ان کی مصلحتیں پوشیدہ ہوتی ہیں۔ (السعدی: ۷۶۵)\nاس آیت میں اس بات کی دلیل ہے کہ اللہ تعالىٰ محض اپنے رحم وکرم کی وجہ سے اپنے بندوں کو بعض دنیاوی عیش وآرائش کے سامان نہیں دیتا ہے، اس کی وضاحت کیجئے؟\nوَمَن يَعۡشُ عَن ذِكۡرِ ٱلرَّحۡمَٰنِ نُقَيِّضۡ لَهُۥ شَيۡطَٰنٗا فَهُوَ لَهُۥ قَرِينٞ ٣٦ وَإِنَّهُمۡ لَيَصُدُّونَهُمۡ عَنِ ٱلسَّبِيلِ وَيَحۡسَبُونَ أَنَّهُم مُّهۡتَدُونَ ٣٧\nاس لئے کہ عموما ہوتا یہ ہے کہ جس پر دنیا کشادہ کر دی جاتی ہے وہ اللہ تعالىٰ کی یاد سے غافل ہوجاتا ہے، چنانچہ فرشتے اس سے متنفر ہوجاتے ہیں، اور شیاطین اس کے ساتھ ہوجاتے ہیں، تو یہ چیز اسے ہر برائی کی طرف کھینچ کر لے جاتی ہے۔ اور جو شخص اللہ تعالىٰ سے ڈرتا، اور ہمہ وقت اسے یاد کرتا رہتا ہے، ایسے شخص کی اللہ تعالىٰ فرشتے کے ذریعہ مدد کرتا ہے، اور وہ فرشتہ اس کا تعاون کرتا ہے۔ (البقاعی: ۷؍۲۷-۲۸)\nاللہ تعالىٰ کے ذکر سے غفلت کے نتیجے میں ہونے والے بعض نقصانات ذکر کیجئے؟\nوَإِنَّهُمۡ لَيَصُدُّونَهُمۡ عَنِ ٱلسَّبِيلِ وَيَحۡسَبُونَ أَنَّهُم مُّهۡتَدُونَ ٣٧\nیہاں پر اگر یہ کہا جائے کہ کیا ایسا شخص معذور سمجھا جائیگا؟ اس حیثیت سے کہ وہ تو یہ سمجھ رہا تھا کہ وہ ہدایت یافتہ اور حق پر ہے، جبکہ معاملہ ایسا نہیں تھا! تو اس کا جواب یہ ہوگا کہ یہ اور اس قسم کے ایسے لوگ معذور نہیں سمجھے جائیں گے جن کی جہالت کا اصل سبب ان کا اللہ کی یاد سے غافل ہونا تھا، جب کہ وہ ہدایت پر قدرت رکھتے تھے۔اوریہ قدرت رکھنے کے باوجود انھوں نے ہدایت ورہنمائی میں بالکل دلچسپی نہیں دکھائی، بلکہ الٹا باطل اور غلط کاموں میں دلچسپی لی، تو اب اصل غلطی بھی انہیں کی ہے، اور اصل جرم بھی انھیں کا ہے۔ (السعدی: ۷۶۶)\nکیا ایسے گمراہ لوگ معذور سمجھے جائیں گے جنھوں نے یہ گما ن کیا ہو کہ وہ ہدایت یافتہ ہیں جبکہ درحقیقت وہ گمراہی کے شکار ہوں؟\nوَلَن يَنفَعَكُمُ ٱلۡيَوۡمَ إِذ ظَّلَمۡتُمۡ أَنَّكُمۡ فِي ٱلۡعَذَابِ مُشۡتَرِكُونَ ٣٩\nیہ بات آخرت میں کافروں سے کہی جائیگی۔ اور اس کا مطلب یہ ہے کہ عذاب میں کافروں کا آپس میں شریک ہونا انھیں کوئی فائدہ نہیں دیگا، اور نہ ہی وہ تسلی اور ایک دوسرے کی مصیبت سے کوئی راحت پائیں گے، جیسا کہ دنیا میں مصیبت زدہ کے ساتھ ہوتا ہے کہ جب وہ کسی اور کو اسی مصیبت میں مبتلا دیکھتا ہے جس میں وہ خود مبتلا ہوتا ہے تو اسے ایک گونا راحت ملتی اور تسلی ہوتی ہے۔ (ابن جزی: ۲؍۳۱۴)\nاس نفسیاتی عذاب کی وضاحت کیجئے جس کا سامنا اللہ تعالىٰ کی یاد سے غافل رہنے والا آخرت میں کرے گا؟\nأَفَأَنتَ تُسۡمِعُ ٱلصُّمَّ أَوۡ تَهۡدِي ٱلۡعُمۡيَ وَمَن كَانَ فِي ضَلَٰلٖ مُّبِينٖ ٤٠\nمطلب یہ ہے کہ ان میں سے کچھ بھی آپ کے ہاتھ میں نہیں ہے، بلکہ اس کا مالک وہ اللہ کی ذات ہے جو ہر چیز پر قادر ہے، اور رہے آپ تو آپ کی ذمہ داری -پیغام کو- محض پہنچا دینا ہے۔ (البقاعی: ۷؍۳۰)\nاللہ تعالىٰ کى طرف دعوت دینے والوں کی اصل ذمہ داری کیا ہے؟\nوَإِنَّهُۥ لَذِكۡرٞ لَّكَ وَلِقَوۡمِكَۖ وَسَوۡفَ تُسۡـَٔلُونَ ٤٤\n(وإنه) میں“ه” کی ضمیر یا تو قرآن کے لئے ہے یا اسلام کے لئے، اور (ذكر ) یہاں پر شرف کے معنى میں ہے، اور آپ صلی اللہ علیہ وسلم کی قوم قریش اور سارے عرب ہیں، چنانچہ بلا شبہ اسلام کے ذریعہ انھیں دنیا وآخرت دونوں میں اسلام کے ذریعہ شرف ملا۔ اور یہی کافی ہے کہ انہوں نے مشرق ومغرب سب کو فتح کرلیا۔ (ابن جزی: ۲؍۳۱۴)\nوہ کون سا شرف ہے جس سے اہل عرب اسلام پر مضبوطی سے عمل پیرا ہونے کی وجہ سے شرف یاب ہوئے؟\nوَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔايَٰتِنَآ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ فَقَالَ إِنِّي رَسُولُ رَبِّ ٱلۡعَٰلَمِينَ ٤٦\nجب اہل عشرت اور مال ودولت اور قوت وسلطنت کے مالک اشخاص کی یہ عادت رہی ہے کہ وہ اپنے پاس آنے والے-رسولوں اور نبیوں- کو حقیر گردانتے اور انھیں ایک طرح سے کمتر سمجھتے ہیں، اور اس طرح کی باطل اور غلط حرکتیں برابر کرتے رہتے ہیں یہاں تک کہ اللہ تعالىٰ ان چیزوں کے ذریعہ جو اس کے رسول ان کے پاس لے کر آتے ہیں انھیں پست کردیتا ہے، چاہے انھیں ہلاک کرکے، یا کسی اور طریقے سے، اگرچہ وہ بہت قوی اور مضبوط ہوں۔ جب واقع ایسا ہی ہے، تو اللہ تعالىٰ نے اسی مناسبت سے یہاں موسى علیہ السلام کا یہ قصہ ذکر کیا جس میں فرعون نے کچھ اسی طرح کی بات کہی تھی، اور پھر اللہ تعالىٰ نے فرعون کو اس کی قوت کے باوجود ہلاک وبرباد کردیا، اور بنی اسرائیل کو ان کی کمزوری کے باوجود نجات دے دی۔ (البقاعی: ۷؍۳۳)\nمالدار اور عیش پرست افراد نصیحت کرنے والوں سے کیسا برتاؤ کرتے ہیں؟ اور دونوں گروہ کے خاتمے کے تئیں اللہ تعالىٰ کی کیا سنت رہی ہے؟\nwords\nوَزُخرُفًاسونا (زخارف).\nوَإِن كُلُّ ذَلِكَ لَمَّايه تو صرف اتنا هي هے.\nيَعشُمنه موڑتا هے/ اندھا بنتا هے.\nنُقَيِّضهم مقرر كرديتے هيں؛ آسان كرديتے هيں.\nقَرِينٌساتھ رهنے والا/ ساتھي.\nبُعدَ المَشرِقَينِجيسے مشرق و مغرب كے مابين دوري هے."]])